INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('a, an', 'A1', 'indefinite article', 'Used before a noun to refer to a single thing or person that has not been mentioned before.', 'sebuah / seorang', 'She bought a book and an apple from the store.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('about', 'A1', 'prep., adv.', 'On the subject of; concerning.', 'tentang', 'They were talking about the new movie that just came out.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('above', 'A1', 'prep., adv.', 'At a higher level or layer than; higher than.', 'di atas', 'A plane flew high above the thick white clouds.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('across', 'A1', 'prep., adv.', 'From one side to the other of; to the other side.', 'menyeberangi / di seberang', 'She carefully walked across the busy street to greet us.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('action', 'A1', 'n.', 'Something done so as to accomplish a purpose.', 'tindakan / aksi', 'The firefighters quick action saved the entire family from the burning house.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('activity', 'A1', 'n.', 'The state or quality of being active; activeness.', 'kegiatan / aktivitas', 'My favorite relaxing activity is reading a good book before going to bed at night.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('actor', 'A1', 'n.', 'A person who performs, plays a part in a theatrical play or film.', 'aktor / pemeran pria', 'The talented actor won an award for his outstanding performance in the film.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('actress', 'A1', 'n.', 'A female who performs on the stage or in films.', 'aktris / pemeran wanita', 'The famous actress delivered a powerful and emotional monologue on stage.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('add', 'A1', 'v.', 'To join or unite', 'menambahkan', 'Please add a little bit more sugar to my coffee to make it taste sweeter.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('address', 'A1', 'n.', 'The name or number of a place where someone lives or works.', 'alamat', 'What is your current email address so I can send you the important documents?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('adult', 'A1', 'n.', 'A person who is fully grown or developed.', 'dewasa', 'The museum offers a special discounted ticket price for adults on weekends.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('advice', 'A1', 'n.', 'An opinion offered in an effort to be helpful.', 'nasihat / saran', 'My wise grandfather gave me some very valuable advice about saving money and investing wisely for the future.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('afraid', 'A1', 'adj.', 'Feeling fear or apprehension; frightened.', 'takut', 'The little girl is terribly afraid of the dark and always sleeps with a nightlight on in her room.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('after', 'A1', 'prep.', 'In the time following; later than.', 'setelah', 'We went for a nice long walk in the park together after having our dinner.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('afternoon', 'A1', 'n.', 'The part of the day from noon or lunchtime until sunset, evening, or suppertime or 6pm.', 'sore / siang hari', 'Lets meet for a cup of coffee on Sunday afternoon at that new cafe downtown.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('again', 'A1', 'adv.', 'Another time; once more.', 'lagi / sekali lagi', 'Could you please say that again more slowly? I did not quite hear what you said clearly.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('age', 'A1', 'n.', 'The whole duration of a being, whether animal, plant, or other kind, being alive.', 'usia / umur', 'She learned how to drive a car at the young age of seventeen years old.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ago', 'A1', 'adv.', 'Before the present time; earlier in time.', 'yang lalu', 'We moved to this beautiful city two years ago and we absolutely love living here.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('agree', 'A1', 'v.', 'To harmonize in opinion, statement, or action; to be in unison or concord; to be or become united or consistent; to concur.', 'setuju', 'I completely and wholeheartedly agree with your thoughtful opinion on this important matter.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('air', 'A1', 'n.', 'The substance constituting earth''s atmosphere, particularly:', 'udara', 'The fresh and clean air in the mountains is absolutely wonderful and refreshing to breathe in deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('airport', 'A1', 'n.', 'An airfield (an area designated for the takeoff and landing of aircraft), including one or more runways and (for commercial airports) one or more passenger terminals.', 'bandara', 'We arrived at the busy airport at least two full hours before our flight was scheduled to depart.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('all', 'A1', 'det., pron.', 'The whole quantity or extent of; every one of.', 'semua', 'All of the students in the class must complete and submit the assignment before the deadline.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('also', 'A1', 'adv.', '(focus) In addition; besides; as well; further; too.', 'juga', 'She is a very talented singer and also plays the piano beautifully and with great skill.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('always', 'A1', 'adv.', 'At all times; on every occasion; forever.', 'selalu', 'My dear grandmother always wakes up at exactly six o clock every single morning without fail.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('amazing', 'A1', 'adj.', 'Causing wonder and amazement', 'luar biasa', 'The gorgeous and colorful sunset over the vast ocean was truly amazing and breathtaking to witness.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('and', 'A1', 'conj.', 'Used to connect words or phrases together.', 'dan', 'I went to the store and bought some fresh bread cold milk and ripe bananas for the week.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('angry', 'A1', 'adj.', 'Feeling or showing anger; furious.', 'marah', 'He was extremely angry when he found out that his brand new car had been stolen from the parking lot.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('animal', 'A1', 'n.', 'In scientific usage, a multicellular organism that is usually mobile, whose cells are not encased in a rigid cell wall', 'hewan / binatang', 'Lions tigers and elephants are all examples of fascinating wild animals that live in nature.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('another', 'A1', 'det./pron.', 'An additional one of the same kind.', 'lagi / satu lagi', 'Would you like to have another warm cup of tea before you leave for work this morning?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('answer', 'A1', 'n., v.', 'A response or reply; something said or done in reaction to a statement or question.', 'menjawab', 'She confidently raised her hand to answer the difficult question that the teacher had just asked the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('any', 'A1', 'det., pron.', 'One or some of a thing, no matter how much or how many.', 'apa pun', 'Do you have any questions at all about the lesson that we just finished covering today in class?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('anyone', 'A1', 'pron.', 'Any person; anybody.', 'siapa pun', 'Is anyone home right now? I knocked on the door several times but unfortunately nobody came to answer it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('anything', 'A1', 'pron.', 'Any thing whatever; something of any kind.', 'apa pun', 'I am so incredibly hungry right now that I could eat just about anything you put in front of me.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('apartment', 'A1', 'n.', 'A complete domicile occupying only part of a building, especially one for rent; a flat.', 'apartemen', 'They currently rent a small but cozy apartment located right in the very heart of the bustling city center.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('apple', 'A1', 'n.', 'A common, round fruit produced by the tree Malus domestica, cultivated in temperate climates.', 'apel', 'She packed a fresh red apple and a sandwich in her lunch bag to take to school with her.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('April', 'A1', 'n.', 'The fourth month of the year, after March and before May.', 'April', 'Her birthday falls in the lovely month of April right in the middle of the beautiful spring season.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('area', 'A1', 'n.', 'A measure of the extent of a surface; it is measured in square units.', 'daerah / area', 'This particular area of the city is widely known for having the best restaurants and cafes around.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('arm', 'A1', 'n.', 'The portion of the upper human appendage, from the shoulder to the wrist and sometimes including the hand.', 'lengan', 'He unfortunately broke his left arm while playing a rough game of football with his friends at school.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('around', 'A1', 'prep., adv.', '(with the verb "to be") Present in the vicinity.', 'sekitar / kira-kira', 'Lets plan to meet around seven o clock this evening at the usual place we always go to.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('arrive', 'A1', 'v.', 'To reach; to get to a certain place.', 'tiba / sampai', 'The train from Jakarta is scheduled to arrive at platform number three in about ten more minutes.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('art', 'A1', 'n.', 'The conscious production or arrangement of sounds, colours, forms, movements, or other elements in a manner that affects the senses and emotions, usually specifically the production of the beautiful in a graphic or plastic medium.', 'seni', 'The local museum has a truly impressive and extensive collection of beautiful modern and contemporary art.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('article', 'A1', 'n.', 'A piece of nonfictional writing such as a story, report, opinion piece, or entry in a newspaper, magazine, journal, dictionary, encyclopedia, etc.', 'artikel', 'I read a very interesting and thought provoking article about the effects of climate change in the newspaper this morning.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('artist', 'A1', 'n.', 'A person who creates art.', 'seniman', 'The incredibly talented artist painted a absolutely stunning and breathtaking landscape of the peaceful green valley.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('as', 'A1', 'prep.', 'Used to indicate that something happens at the same time as something else.', 'sebagai', 'She works full time as a dedicated and passionate teacher at the local elementary school in our neighborhood.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ask', 'A1', 'v.', 'To inquire; to request information or action.', 'bertanya', 'May I please ask you a personal question about your background and experience?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('at', 'A1', 'prep.', 'Expressing location or time.', 'di / pada', 'I will meet you at the bus stop right after I finish my work for the day.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('August', 'A1', 'n.', 'The eighth month of the year, after July and before September.', 'Agustus', 'We usually go on a family vacation to the beach for two weeks during the month of August every summer.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('aunt', 'A1', 'n.', 'The sister or sister-in-law of one’s parent.', 'bibi', 'My wonderful aunt lives in a charming small town located not too far from the beautiful scenic coast.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('autumn', 'A1', 'n.', 'Traditionally the third of the four seasons, when deciduous trees lose their leaves; typically regarded as being from September 24 to December 22 in parts of the Northern Hemisphere, and the months of March, April and May in the Southern Hemisphere.', 'musim gugur', 'The leaves on the trees gradually turn brilliant shades of golden yellow and orange during the autumn season.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('away', 'A1', 'adv.', 'From a place, hence.', 'pergi / menjauh', 'She carefully put the book away on the shelf after she had finished reading the last chapter.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('baby', 'A1', 'n.', 'A very young human, particularly from birth to a couple of years old or until walking is fully mastered.', 'bayi', 'The newborn baby is sleeping peacefully and quietly in her cozy warm crib in the nursery.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('back', 'A1', 'n., adv.', 'In the opposite direction from the front; toward the rear.', 'kembali', 'I will call you back later this evening after I get home from work and have dinner.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bad', 'A1', 'adj.', 'Of poor quality or a low standard; unfavorable.', 'buruk / jelek', 'The weather outside is really bad today - its pouring heavy rain and the wind is blowing very strongly.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bag', 'A1', 'n.', 'A flexible container made of cloth, paper, plastic, etc.', 'tas', 'She packed all her clothes and essentials into a large sturdy travel bag for her long trip abroad.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ball', 'A1', 'n.', 'A solid or hollow sphere, or roughly spherical mass.', 'bola', 'The young children are happily playing with a bright red ball in the park this afternoon.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('banana', 'A1', 'n.', 'An elongated curved tropical fruit that grows in bunches and has a creamy flesh and a smooth skin.', 'pisang', 'I make it a habit to eat a fresh banana every single morning for breakfast to get some energy.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('band', 'A1', 'n.', 'A strip of material used for strengthening or coupling.', 'grup musik / band', 'My all time favorite musical band is performing live at the stadium tonight and I have tickets to go see them!');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bank (money)', 'A1', 'n.', 'An institution where one can place and borrow money and take care of financial affairs.', 'bank', 'I need to go to the bank to withdraw some money.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bath', 'A1', 'n.', 'A tub or pool which is used for bathing: bathtub.', 'mandi', 'After a long and tiring day at work she enjoys taking a relaxing hot bath to unwind and de stress.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bathroom', 'A1', 'n.', 'A room containing a shower and/or bathtub, and (typically but not necessarily) a toilet.', 'kamar mandi', 'The bathroom is located down the hall way on the left hand side of the corridor.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('be', 'A1', 'v., auxiliary v.', 'To exist; to have a specific state or quality.', 'ada / menjadi', 'To be or not to be - that is the famous question from Shakespeare s classic play Hamlet.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('beach', 'A1', 'n.', 'The shore of a body of water, especially when sandy or pebbly.', 'pantai', 'We spent the entire glorious day relaxing on the beautiful sandy beach and swimming in the clear warm ocean water.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('beautiful', 'A1', 'adj.', 'Pleasing the senses aesthetically; very attractive.', 'indah / cantik', 'The garden looks absolutely beautiful and vibrant in the spring when all the flowers are in full colorful bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('because', 'A1', 'conj.', 'For the reason that; since.', 'karena', 'I decided to stay home from the party because I was not feeling very well and needed to rest.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('become', 'A1', 'v.', 'To arrive, come (to a place).', 'menjadi', 'She has always dreamed of wanting to become a successful doctor when she grows up and completes her education.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bed', 'A1', 'n.', 'A piece of furniture, usually flat and soft, on which to rest or sleep.', 'tempat tidur', 'I usually like to read a few chapters of a good book before I go to bed at night.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bedroom', 'A1', 'n.', 'A room in a house where a bed is kept for sleeping.', 'kamar tidur', 'My bedroom is the coziest and most comfortable room in our entire house.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('beer', 'A1', 'n.', 'An alcoholic drink fermented from starch material, commonly barley malt, often with hops or some other substance to impart a bitter flavor.', 'bir', 'He ordered a cold glass of refreshing beer to go along with his dinner at the restaurant.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('before', 'A1', 'prep.', 'During the period of time preceding something.', 'sebelum', 'Please make sure to finish all your homework before you sit down to have your dinner tonight.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('begin', 'A1', 'v.', 'To start; to commence; to come into being.', 'mulai / memulai', 'The highly anticipated concert will begin at exactly eight o clock sharp so please arrive on time.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('beginning', 'A1', 'n.', 'The start or first part of something.', 'awal / permulaan', 'At the very beginning of the movie the main hero is just a young child living in a small village.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('behind', 'A1', 'prep., adv.', 'At or to the far side of something; at the back of.', 'di belakang', 'The sneaky cat is hiding behind the large sofa in the living room waiting to pounce on its toy.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('believe', 'A1', 'v.', 'To accept as true, particularly without absolute certainty (i.e., as opposed to knowing)', 'percaya', 'I strongly believe that honesty and integrity are always the best policies to follow in life.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('below', 'A1', 'adv., prep.', 'At a lower level or position.', 'di bawah', 'The temperature outside dropped dramatically below freezing point zero last night during the cold winter storm.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('best', 'A1', 'adj.', 'Most', 'terbaik', 'She has been my absolute best friend since we were both in kindergarten together many years ago.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('better', 'A1', 'adj.', 'Of a more excellent quality or standard.', 'lebih baik', 'Your English language skills are getting better and better every single day with consistent practice.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('between', 'A1', 'prep.', 'In the space separating two things.', 'antara', 'The friendly conversation between the two world leaders was very productive and positive overall.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bicycle', 'A1', 'n.', 'A vehicle that has two wheels, one behind the other, a steering handle, and a saddle seat or seats and is usually propelled by the action of a rider’s feet upon pedals.', 'sepeda', 'He rides his bicycle to work every single morning as a way to get some exercise and save money on transportation costs.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('big', 'A1', 'adj.', 'Of considerable size or extent; large.', 'besar', 'They live in a really big and spacious house with a beautiful garden full of colorful flowers out in the backyard.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bike', 'A1', 'n.', 'A vehicle that has two wheels, one behind the other, a steering handle, and a saddle seat or seats and is usually propelled by the action of a rider’s feet upon pedals.', 'sepeda / motor', 'I securely parked my bike near the main entrance of the building using the metal bike rack provided.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bill', 'A1', 'n.', 'Any of various bladed or pointed hand weapons, originally designating an Anglo-Saxon sword, and later a weapon of infantry, especially in the 14th and 15th centuries, commonly consisting of a broad, heavy, double-edged, hook-shaped blade, with a short pike at the back and another at the top, attached to the end of a long staff.', 'tagihan', 'Excuse me waiter could you please bring me the bill when you get a chance? I am ready to pay now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bird', 'A1', 'n.', 'A member of the class of animals Aves in the phylum Chordata, characterized by being warm-blooded, having feathers and wings usually capable of flight, and laying eggs.', 'burung', 'A beautiful colorful bird landed on the windowsill this morning and sang a lovely song.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('birthday', 'A1', 'n.', 'The anniversary of the day on which someone is born.', 'ulang tahun', 'Happy birthday to you! I sincerely hope you have a truly wonderful and memorable day celebrating.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('black', 'A1', 'adj., n.', 'The colour/color perceived in the absence of light, but also when no light is reflected, but rather absorbed.', 'hitam', 'She wore a very elegant and stylish black dress to the formal party last night.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('blog', 'A1', 'n.', 'A website that allows users to reflect, share opinions, and discuss various topics in the form of an online journal, sometimes letting readers comment on their posts. Most blogs are written in a slightly informal tone (personal journals, news, businesses, etc.)', 'blog', 'She writes a very popular and widely read blog about healthy cooking nutritious recipes and wellness tips.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('blonde', 'A1', 'adj.', 'Having fair hair; light-colored.', 'pirang', 'She has beautiful long flowing blonde hair and stunning bright blue eyes.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('blue', 'A1', 'adj., n.', 'The colour of the clear sky or the deep sea, between green and violet in the visible spectrum, and one of the primary additive colours for transmitted light; the colour obtained by subtracting red and green from white light using magenta and cyan filters; or any colour resembling this.', 'biru', 'The clear sky above us is a brilliant shade of bright blue today without a single cloud in sight.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('boat', 'A1', 'n.', 'A craft used for transportation of goods, fishing, racing, recreational cruising, or military use on or in the water, propelled by oars or outboard motor or inboard motor or by wind.', 'perahu / kapal', 'We took a lovely scenic boat ride across the calm peaceful lake to reach the small island on the other side.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('body', 'A1', 'n.', 'The physical structure of a person or animal.', 'tubuh', 'Regular physical exercise is very good and beneficial for both your body and your mind and overall health.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('book', 'A1', 'n.', 'A written or printed work of pages bound together.', 'buku', 'I am currently reading a truly fascinating and captivating book about space exploration and the mysteries of the universe.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('boot', 'A1', 'n.', 'A heavy shoe that covers part of the leg.', 'sepatu bot', 'She wore sturdy leather boots to protect her feet while walking through the deep snow.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bored', 'A1', 'adj.', 'Suffering from boredom', 'bosan', 'The young children were extremely bored and restless during the long and tedious lecture that seemed to go on forever.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('boring', 'A1', 'adj.', 'Causing boredom', 'membosankan', 'The movie we watched last night was so incredibly boring that I unfortunately ended up falling asleep halfway through it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('born', 'A1', 'v.', 'To carry or convey, literally or figuratively.', 'dilahirkan', 'She was born in a small peaceful village in the year 1995 and grew up surrounded by beautiful nature.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('both', 'A1', 'det./pron.', 'The two; the one as well as the other.', 'keduanya', 'Both of my beloved parents are dedicated and passionate teachers at the same local elementary school.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bottle', 'A1', 'n.', 'A container, typically made of glass or plastic and having a tapered neck, used primarily for holding liquids.', 'botol', 'Please remember to recycle that empty plastic bottle after you finish drinking the water from it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('box', 'A1', 'n.', 'Senses relating to a three-dimensional object or space.', 'kotak', 'The special birthday gift was carefully wrapped and placed inside a beautiful decorative box.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('boy', 'A1', 'n.', 'A male child or young man.', 'anak laki-laki', 'The young boy enthusiastically kicked the ball straight into the goal scoring the winning point for his team.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('boyfriend', 'A1', 'n.', 'A male partner in an unmarried romantic relationship.', 'pacar', 'She officially introduced her boyfriend to her parents during the family dinner gathering last weekend.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bread', 'A1', 'n.', 'A foodstuff made by baking dough made from cereals.', 'roti', 'I bought a fresh warm loaf of bread from the local bakery on my way home from work.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('break', 'A1', 'v., n.', 'To separate into pieces; to damage or stop working.', 'istirahat', 'Lets take a short break from work and go grab a cup of coffee together to recharge our energy.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('breakfast', 'A1', 'n.', 'The first meal of the day, usually eaten in the morning.', 'sarapan', 'I usually have a simple breakfast consisting of toast eggs and a glass of fresh orange juice.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bring', 'A1', 'v.', 'To carry or convey to a place; to cause to come.', 'membawa', 'Please do not forget to bring your notebook and pen to class with you tomorrow morning.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('brother', 'A1', 'n.', 'Son of the same parents as another person.', 'saudara laki-laki', 'My older brother is currently studying engineering at a prestigious university in the city.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('brown', 'A1', 'adj., n.', 'A color produced by mixing red, yellow, and blue.', 'cokelat', 'She has the most beautiful warm brown eyes that sparkle when she smiles happily.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('build', 'A1', 'v.', 'To form', 'membangun', 'They have plans to build a brand new modern school building in our neighborhood next year.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('building', 'A1', 'n.', 'The act or process by which something is built; construction.', 'gedung / bangunan', 'The tallest building in the entire city has an impressive fifty floors and offers amazing panoramic views from the top.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bus', 'A1', 'n.', 'A motor vehicle for transporting large numbers of people along roads.', 'bis', 'I take the public bus to work every single day because it is the most convenient and affordable transportation option available.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('business', 'A1', 'n.', 'A specific commercial enterprise or establishment.', 'bisnis', 'She successfully runs her own profitable online business from the comfort of her home office.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('busy', 'A1', 'adj.', 'Having a great deal to do; occupied.', 'sibuk', 'The popular restaurant is always incredibly busy and crowded on weekend nights so we made a reservation in advance.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('but', 'A1', 'conj.', 'Used to introduce a phrase that contrasts with what was said previously.', 'tetapi', 'I really wanted to go to the party and have fun with my friends but unfortunately I was feeling far too exhausted and tired to go out.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('butter', 'A1', 'n.', 'A soft, fatty foodstuff made by churning the cream of milk (generally cow''s milk).', 'mentega', 'Please spread some creamy butter on the warm freshly toasted bread for breakfast this morning.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('buy', 'A1', 'v.', 'To obtain something in exchange for payment.', 'membeli', 'I need to go to the supermarket to buy some groceries and supplies for the upcoming week.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('by', 'A1', 'prep.', 'Indicating the person or thing that does something.', 'di samping / dekat', 'She chose a seat by the window so she could enjoy the beautiful view during the long flight.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bye', 'A1', 'exclam.', 'Used to express farewell.', 'selamat tinggal / dadah', 'Bye! See you again tomorrow! Have a great evening!');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cafe', 'A1', 'n.', 'A convenience store, originally one that sold coffee and similar basic items.', 'kafe', 'The concept of cafe plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cake', 'A1', 'n.', 'A rich, sweet dessert food, typically made of flour, sugar and eggs and baked in an oven, and often covered in icing.', 'kue', 'She baked a delicious homemade chocolate cake for her best friends birthday celebration party.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('call', 'A1', 'v., n.', 'To cry out; to name; to contact by telephone.', 'menelepon', 'I will call you on the phone as soon as I safely arrive at my destination later tonight.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('camera', 'A1', 'n.', 'A device for taking still or moving pictures or photographs.', 'kamera', 'Please do not forget to bring your camera along on the trip so we can capture and preserve all the wonderful memories and beautiful moments.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('can1', 'A1', 'modal v.', 'To be able to; to have the ability to do something.', 'dapat / bisa', 'You can1 finish your homework before you go out to play.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cannot', 'A1', 'modal v.', 'Can not; be unable to.', 'tidak dapat / tidak bisa', 'We cannot leave now if we want to catch the train on time.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('capital', 'A1', 'n., adj.', 'Already-produced durable goods available for use as a factor of production, such as steam shovels', 'ibukota / modal', 'Can you please explain to me what the capital is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('car', 'A1', 'n.', 'A wheeled vehicle that moves independently, with at least three wheels, powered mechanically, steered by a driver and mostly for personal transportation.', 'mobil', 'She drives her reliable car to work every single morning to avoid the hassle of public transportation.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('card', 'A1', 'n.', 'A piece of thick paper used for writing or playing games.', 'kartu', 'I sent my dear grandmother a beautiful handwritten birthday card in the mail to wish her a happy day.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('career', 'A1', 'n.', 'One''s calling in life', 'karier', 'She has built a very successful and rewarding career in the field of journalism and media over the years.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('carrot', 'A1', 'n.', 'A vegetable with a nutritious, juicy, sweet root that is often orange in colour, Daucus carota, especially the subspecies sativus in the family Apiaceae.', 'wortel', 'Please add some freshly sliced carrots to the simmering soup for extra flavor nutrition and color.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('carry', 'A1', 'v.', 'To hold and move something to another place.', 'membawa', 'Could you kindly help me carry these heavy grocery bags into the kitchen please?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cat', 'A1', 'n.', 'An animal of the family Felidae:', 'kucing', 'The lazy cat curled up into a cozy ball on the soft sofa and peacefully fell fast asleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('CD', 'A1', 'n.', 'A small disc used for storing music or data.', 'CD', 'I still have a large collection of music CDs from back in the nineteen nineties stored away in a box somewhere.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cent', 'A1', 'n.', '(money) A subunit of currency equal to one-hundredth of the main unit of currency in many countries. Symbol: ¢.', 'sen', 'The candy at the old corner store only costs fifty cents each which is very cheap and affordable.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('centre', 'A1', 'n.', 'The point in the interior of a circle that is equidistant from all points on the circumference.', 'pusat', 'The large shopping centre is conveniently located right in the downtown area of the city.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('century', 'A1', 'n.', 'A period of 100 consecutive years; often specifically a numbered period with conventional start and end dates, e.g., the twentieth century, which stretches from (strictly) 1901 through 2000, or (informally) 1900 through 1999. The first century AD was from 1 to 100.', 'abad', 'The ancient castle was originally built several centuries ago in the fourteenth century.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('chair', 'A1', 'n.', 'An item of furniture used to sit on or in, comprising a seat, legs, back, and sometimes arm rests, for use by one person. Compare stool, couch, sofa, settee, loveseat and bench.', 'kursi', 'Please pull up a chair and come join our interesting conversation about the latest news.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('change', 'A1', 'v., n.', 'To make or become different; to alter.', 'mengubah', 'We unfortunately need to change our original plans due to the unexpected bad weather that is forecasted for today.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('chart', 'A1', 'n.', 'A graphical representation of data; a map or diagram.', 'grafik / bagan', 'The colorful chart clearly illustrates the impressive growth of the company over the past five successful years.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cheap', 'A1', 'adj.', 'Low in price; inexpensive; of poor quality.', 'murah', 'The budget hotel we stayed at was surprisingly very cheap but it was also remarkably clean and comfortable.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('check', 'A1', 'v.', 'To examine or inspect something for accuracy or quality.', 'memeriksa', 'Please carefully check all your answers one more time before you finally submit the test paper.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cheese', 'A1', 'n.', 'A dairy product made from curdled or cultured milk.', 'keju', 'I would like to order a grilled cheese sandwich with a warm bowl of tomato soup for lunch today please.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('chicken', 'A1', 'n.', 'A domestic fowl, Gallus gallus, especially when young.', 'ayam', 'We had delicious roast chicken with roasted vegetables for our family dinner last night.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('child', 'A1', 'n.', 'A person who has not yet reached adulthood, whether natural (puberty), cultural (initiation), or legal (majority)', 'anak', 'The young child was playing happily and carefreely in the sunny garden outside.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('chocolate', 'A1', 'n.', 'A food made from ground roasted cocoa beans.', 'cokelat', 'Rich dark chocolate is my absolute favorite sweet treat and dessert indulgence.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('choose', 'A1', 'v.', 'To pick; to make the choice of; to select.', 'memilih', 'Please take all the time you need to carefully choose the right career path that suits you best.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cinema', 'A1', 'n.', 'A movie theatre, a movie house', 'bioskop', 'Lets go to the cinema this weekend to watch that new highly anticipated film that just came out.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('city', 'A1', 'n.', 'A large settlement, bigger than a town; sometimes with a specific legal definition, depending on the place.', 'kota', 'New York City is widely considered to be one of the most vibrant exciting and dynamic cities anywhere in the entire world.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('class', 'A1', 'n.', 'A group, collection, category or set sharing characteristics or attributes.', 'kelas', 'She diligently attends an English language class every Tuesday evening after she finishes work for the day.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('classroom', 'A1', 'n.', 'A room, often in a school, where classes take place', 'ruang kelas', 'The classroom was completely quiet and silent during the important final exam.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('clean', 'A1', 'adj., v.', 'Free from dirt or impurities; not dirty.', 'membersihkan', 'The housekeeper comes to thoroughly clean the entire house every single Friday without fail.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('climb', 'A1', 'v.', 'To go up; to ascend.', 'mendaki', 'They have the ambitious goal to climb the famous Mount Everest next year if the weather conditions permit.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('clock', 'A1', 'n.', 'An instrument for measuring time.', 'jam', 'The old fashioned clock hanging on the wall indicates that it is currently ten minutes past three in the afternoon.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('close1', 'A1', 'v.', 'To shut; to move so as to cover an opening.', 'penutupan', 'Can you please close1 this task for me? I would really appreciate your help.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('clothes', 'A1', 'n.', 'A woven fabric such as used in dressing, decorating, cleaning or other practical use.', 'pakaian', 'She packed plenty of warm clothes for the cold mountain trip because she knew it would be freezing up there.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('club', 'A1', 'n.', 'A group of people with a common interest.', 'klub', 'He decided to join the schools chess club last semester to pursue his interest in the game.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('coat', 'A1', 'n.', 'An outer garment covering the upper torso and arms.Wp', 'mantel / jas', 'Please wear a warm heavy coat when you go outside because it is absolutely freezing cold out there today.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('coffee', 'A1', 'n.', 'A beverage made by infusing the beans of the coffee plant in hot water.', 'kopi', 'I enjoy drinking a hot cup of black coffee every single morning to help me wake up and feel energized for the day ahead.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cold', 'A1', 'adj., n.', 'Of or at a low temperature; not warm.', 'dingin', 'I feel really cold and chilly; could you please turn up the heater to warm up the room a bit more?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('college', 'A1', 'n.', 'A corporate group; a group of colleagues.', 'perguruan tinggi', 'She is currently attending college to study marine biology which has always been her passion and dream.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('colour', 'A1', 'n.', 'A visual property of light.', 'warna', 'What colour is your brand new car that you just bought recently?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('come', 'A1', 'v.', 'To move or travel toward the speaker or toward a particular place.', 'datang', 'You are all warmly invited to come to my birthday party this coming Saturday evening at my house.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('common', 'A1', 'adj.', 'Happening often; shared by many; ordinary.', 'umum', 'English has become a very common and widely used language for international business communication and global trade.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('company', 'A1', 'n.', 'A team; a group of people who work together professionally.', 'perusahaan', 'She currently works for a successful technology software company located in Silicon Valley California.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('compare', 'A1', 'v.', 'To examine for similarities and differences.', 'membandingkan', 'Try not to constantly compare yourself to other people; instead focus on your own personal growth progress and journey through life.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('complete', 'A1', 'adj., v.', 'To finish making or doing; to bring to an end.', 'menyelesaikan', 'Please make sure to complete the entire assignment and submit it by Friday afternoon at the very latest.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('computer', 'A1', 'n.', 'An electronic device for processing data.', 'komputer', 'She relies on her reliable laptop computer for both her professional work and personal entertainment activities.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('concert', 'A1', 'n.', 'A live musical performance.', 'konser', 'I read a very interesting article about the concert in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('conversation', 'A1', 'n.', 'Expression and exchange of individual ideas through talking with other people', 'percakapan', 'We had a very interesting and engaging conversation about modern art and its impact on society and culture today.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cook', 'A1', 'v.', 'To prepare food for eating by applying heat.', 'memasak', 'My wonderful mother patiently taught me how to cook a variety of delicious traditional Indonesian dishes from scratch when I was growing up as a child.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cooking', 'A1', 'n.', 'The process of preparing food by using heat.', 'memasak', 'The concept of cooking plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cool', 'A1', 'adj.', 'Having a slightly low temperature; mildly cold.', 'sejuk / dingin', 'The fresh water in the mountain stream is wonderfully cool and incredibly refreshing to drink on a hot summer day.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('correct', 'A1', 'adj., v.', 'Free from error; true; accurate.', 'benar', 'Your answer to the question is absolutely correct. Very well done and excellent work on solving that difficult problem!');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cost', 'A1', 'n., v.', 'To incur a charge of; to require payment of a (specified) price.', 'biaya / harga', 'How much does this stylish leather jacket actually cost? I am very curious to know the price before I decide whether or not to buy it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('could', 'A1', 'modal v.', 'Used to indicate possibility or ability in the past.', 'bisa / dapat', 'I could help you with that if you need my assistance.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('country', 'A1', 'n.', '(chiefly British) An area of land; a district, region.', 'negara', 'Indonesia is a truly beautiful and diverse country consisting of thousands of different islands each with its own unique culture traditions and natural wonders.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('course', 'A1', 'n.', 'A sequence of events.', 'kursus / mata kuliah', 'She is currently taking an intensive online course in digital marketing to enhance her professional skills and advance her career prospects.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cousin', 'A1', 'n.', 'A child of your aunt or uncle.', 'sepupu', 'My cousin who lives in Australia is coming to visit us here for a couple of weeks next month during the summer holiday break.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cow', 'A1', 'n.', 'A large animal kept for milk or meat.', 'sapi', 'The healthy brown and white cows were peacefully grazing on the fresh green grass in the lush open pasture.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cream', 'A1', 'n.', 'The fatty part of milk; a thick liquid or semi-solid cosmetic.', 'krem / krim', 'The concept of cream plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('create', 'A1', 'v.', 'To bring into existence.', 'menciptakan', 'The talented artist loves to create beautiful and meaningful sculptures using recycled and reclaimed materials found in nature and everyday life.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('culture', 'A1', 'n.', 'The arts, customs, lifestyles, background, and habits that characterize a particular society or nation.', 'budaya', 'I truly love traveling and learning about different cultures their unique traditions customs and ways of life.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cup', 'A1', 'n.', 'A small container for drinking.', 'cangkir', 'Would you like to have a nice hot soothing cup of chamomile tea before you go to bed tonight?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('customer', 'A1', 'n.', 'A patron, a client; one who purchases or receives a product or service from a business or merchant, or intends to do so.', 'pelanggan', 'The quality of customer service and support at this particular store is truly outstanding and excellent in every way.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cut', 'A1', 'v.', 'To divide or make an incision with a sharp-edged tool.', 'memotong / mengiris', 'Please be extremely careful and cautious not to accidentally cut yourself with that very sharp kitchen knife while you are chopping the vegetables for dinner.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dad', 'A1', 'n.', 'A father, a male parent.', 'ayah', 'My wonderful dad patiently taught me how to ride a bicycle for the very first time when I was just five years old.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dance', 'A1', 'n., v.', 'To move rhythmically to music, typically following steps.', 'menari', 'She absolutely loves to dance energetically to lively Latin American music at the club with her friends on weekend nights.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dancer', 'A1', 'n.', 'A person who dances, usually as a job or profession.', 'penari', 'The dancer is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dancing', 'A1', 'n.', 'The activity of taking part in a dance.', 'menari / tarian', 'The teacher gave a clear and thorough explanation about the dancing to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dangerous', 'A1', 'adj.', 'Likely to cause harm or injury; risky.', 'berbahaya', 'It is extremely dangerous and risky to attempt to swim in the fast flowing river during a heavy storm when the water levels are dangerously high and unpredictable.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dark', 'A1', 'adj.', 'Having an absolute or (more often) relative lack of light.', 'gelap', 'The room was so extremely dark and pitch black that I could not see anything at all in front of me even with my eyes wide open and adjusted to the darkness.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('date', 'A1', 'n.', 'The fruit of the date palm, Phoenix dactylifera, somewhat in the shape of an olive, containing a soft, sweet pulp and enclosing a hard kernel.', 'tanggal', 'What is todays date? I seem to have completely lost track of the days while being on vacation and relaxing.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('daughter', 'A1', 'n.', 'One’s female offspring.', 'putri / anak perempuan', 'Her young daughter just recently started attending elementary school for the very first time this fall and she absolutely loves it and is so excited to learn new things every day.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('day', 'A1', 'n.', 'Any period of 24 hours.', 'hari', 'It has been an incredibly long and tiring day at work today and I am really looking forward to finally going home to rest and relax.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dear', 'A1', 'adj.', 'Regarded with deep affection; expensive.', 'sayang / tersayang', 'My dearest and most beloved friend I have missed you so very much and I am really looking forward to finally seeing you again in person soon.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('December', 'A1', 'n.', 'The twelfth and last month of the year.', 'Desember', 'She has a deep interest in learning more about the december and understanding its importance in our daily lives and how it affects us all in various ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('decide', 'A1', 'v.', 'To resolve (a contest, problem, dispute, etc.); to choose, determine, or settle', 'memutuskan', 'I simply cannot make up my mind and decide which beautiful dress to wear to the formal party this weekend.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('delicious', 'A1', 'adj.', 'Pleasing to taste; tasty.', 'lezat / enak', 'The homemade traditional Italian pasta dish at that cozy little family owned restaurant was absolutely delicious and incredibly satisfying to eat.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('describe', 'A1', 'v.', 'To represent in words.', 'menggambarkan / mendeskripsikan', 'Could you please try to describe in as much detail as possible exactly what happened and what you witnessed on that fateful night?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('description', 'A1', 'n.', 'A sketch or account of anything in words; a portraiture or representation in language; an enumeration of the essential qualities of a thing or species.', 'deskripsi', 'The detailed job description that was posted on the company website includes the responsibility of managing and leading a dedicated team of ten talented people.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('design', 'A1', 'n., v.', 'To create or plan something with a specific purpose.', 'desain', 'She studied graphic design at a prestigious art school in the city and now works as a creative professional designer for a top design agency.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('desk', 'A1', 'n.', 'A table, frame, or case, in past centuries usually with a sloping top but now usually with a flat top, for the use of writers and readers. It often has a drawer or repository underneath.', 'meja', 'She sat down at her neat and organized desk and immediately began working diligently on completing the important report that she needed to finish by the end of the day.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('detail', 'A1', 'n.', 'Something small enough to escape casual notice.', 'detail / rincian', 'Could you please explain the proposed plan in greater detail with more specific information so that I can fully understand and grasp all the important aspects of it before we proceed?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dialogue', 'A1', 'n.', 'A conversation or other form of discourse between two or more individuals.', 'dialog', 'The heartfelt and emotional dialogue between the two main characters in the play was incredibly moving and powerful and deeply touched the hearts of everyone in the audience who was watching.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dictionary', 'A1', 'n.', 'A reference work with a list of words from one or more languages, normally ordered alphabetically, explaining each word''s meaning, and sometimes containing information on its etymology, pronunciation, usage, translations, and other data.', 'kamus', 'If you ever come across any unfamiliar words while you are reading a book or article you should always look them up in a reliable dictionary to find out what they mean and how to use them properly.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('die', 'A1', 'v.', 'To stop living; to become dead; to undergo death.', 'mati', 'The beautiful colorful flowers in the garden will eventually wither and die if you forget to regularly water them and take proper care of them.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('diet', 'A1', 'n.', 'The food and beverage a person or animal consumes.', 'diet / pola makan', 'Maintaining a healthy balanced and nutritious diet that includes plenty of fresh fruits vegetables whole grains and lean proteins is extremely important for your overall health and well being.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('difference', 'A1', 'n.', 'The quality of being different.', 'perbedaan', 'Can you please tell me what the main difference is between these two beautiful paintings that look almost identical to me at first glance?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('different', 'A1', 'adj.', 'Not the same; distinct; separate.', 'berbeda', 'There are many completely different approaches and methods that you can use to effectively solve this particular problem depending on your personal preferences and the specific circumstances of the situation.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('difficult', 'A1', 'adj.', 'Hard to do; requiring effort or skill.', 'sulit', 'The final mathematics exam at the end of the semester was extremely difficult and challenging for most of the students in the class to complete successfully within the allotted time.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dinner', 'A1', 'n.', 'A midday meal (in a context in which the evening meal is called supper or tea).', 'makan malam', 'Our entire family always makes it a priority to have dinner together around the table every evening at seven o clock sharing stories about our respective days and enjoying each others company over a delicious home cooked meal.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dirty', 'A1', 'adj.', 'Marked with dirt; not clean.', 'kotor', 'The young childrens hands and clothes were extremely dirty and covered in mud after they had spent the entire afternoon happily playing outside in the garden getting messy and having fun.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('discuss', 'A1', 'v.', 'To talk about in detail; to debate.', 'membahas / mendiskusikan', 'We really need to sit down together and thoroughly discuss the project timeline budget and deliverables in more detail sometime this week before we can move forward with the implementation phase.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dish', 'A1', 'n.', 'A shallow container for serving food; a type of food.', 'piring', 'After we finished eating our delicious meal she kindly volunteered to wash all the dirty dishes clean and put them away neatly in the kitchen cupboard.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('do1', 'A1', 'v., auxiliary v.', 'To perform or carry out an action.', 'melakukan', 'She do1 going to the store after she finishes work.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('doctor', 'A1', 'n.', 'A physician; a member of the medical profession; one who is trained and licensed to heal the sick or injured. The final examination and qualification may award a doctor degree in which case the post-nominal letters are D.O., DPM, M.D., DMD, DDS, in the US or MBBS in the UK.', 'dokter', 'The concept of doctor plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dog', 'A1', 'n.', 'A mammal, Canis familiaris or Canis lupus familiaris, that has been domesticated for thousands of years, of highly variable appearance due to human breeding.', 'anjing', 'Can you please explain to me what the dog is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dollar', 'A1', 'n.', 'Official designation for currency in some parts of the world, including Canada, the United States, Australia, New Zealand, Hong Kong, and elsewhere. Its symbol is $.', 'dolar', 'Can you please explain to me what the dollar is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('door', 'A1', 'n.', 'A portal of entry into a building, room, or vehicle, consisting of a rigid plane movable on a hinge. Doors are frequently made of wood or metal. May have a handle to help open and close, a latch to hold the door closed and a lock that ensures the door cannot be opened without the key.', 'pintu', 'I found an insightful article about the door in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('down', 'A1', 'adv., prep.', 'Toward or in a lower place or position.', 'ke bawah / turun', 'She carefully walked down the steep stairs holding onto the railing.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('downstairs', 'A1', 'adv.', 'On or to a lower floor of a building.', 'di lantai bawah', 'She spoke downstairs during the important meeting last week.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('draw', 'A1', 'v.', 'To create a picture or diagram with a pen, pencil, or other tool.', 'menggambar', 'She needs to draw before the deadline to avoid any penalties or problems.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dress', 'A1', 'n., v.', 'To put on clothes; to wear formal clothes.', 'gaun / berpakaian', 'I found an insightful article about the dress in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('drink', 'A1', 'n., v.', 'To consume (a liquid) through the mouth.', 'minum', 'Can you please explain to me what the drink is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('drive', 'A1', 'v.', 'To operate and control a motor vehicle.', 'dorongan / semangat', 'She would like to learn how to drive correctly from an experienced teacher.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('driver', 'A1', 'n.', 'One who drives something, in any sense of the verb to drive.', 'pengemudi', 'The teacher gave a clear and thorough explanation about the driver to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('during', 'A1', 'prep.', 'For all of a given time interval.', 'selama', 'The restaurant is located during the main street in the town center.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('DVD', 'A1', 'n.', 'A disc used for storing movies and other video data.', 'DVD', 'She has been studying the dVD for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('each', 'A1', 'det./pron./adv.', 'Every one of two or more people or things, considered separately.', 'masing-masing', 'He picked each flower from the garden for his mother.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ear', 'A1', 'n.', 'The organ of hearing, consisting of the pinna, auditory canal, eardrum, malleus, incus, stapes and cochlea.', 'telinga', 'He wrote a comprehensive and detailed report about the ear for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('early', 'A1', 'adj., adv.', 'Before the expected or usual time.', 'awal / pagi-pagi', 'The view from the top of the mountain was absolutely early beyond words or description.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('east', 'A1', 'n., adj., adv.', 'One of the four principal compass points, specifically 90°, conventionally directed to the right on maps; the direction of the rising sun at an equinox. Abbreviated as E.', 'timur', 'I read a very interesting article about the east in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('easy', 'A1', 'adj.', 'Achieved without great effort; simple.', 'mudah', 'The test was much easier than I had expected it to be.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('eat', 'A1', 'v.', 'To consume solid food by putting it into the mouth and swallowing.', 'makan', 'It is important to know when to eat and when to wait for the right moment.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('egg', 'A1', 'n.', 'An approximately spherical or ellipsoidal body produced by birds, reptiles, insects and other animals, housing the embryo during its development.', 'telur', 'They had a very productive and engaging discussion about the egg during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('eight', 'A1', 'number', 'The number 8.', 'delapan', 'There are eight students in the classroom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('eighteen', 'A1', 'number', 'The cardinal number occurring after seventeen and before nineteen, represented in Roman numerals as XVIII and in Arabic numerals as 18.', 'delapan belas', 'The recipe requires eighteen cups of flour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('eighty', 'A1', 'number', 'The cardinal number occurring after seventy-nine and before eighty-one, represented in Roman numerals as LXXX and in Arabic numerals as 80.', 'delapan puluh', 'The recipe requires eighty cups of flour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('elephant', 'A1', 'n.', 'A mammal of the order Proboscidea, having a trunk, and two large ivory tusks jutting from the upper jaw.', 'gajah', 'They had a very productive and engaging discussion about the elephant during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('eleven', 'A1', 'number', 'The number 11.', 'sebelas', 'There are exactly eleven items left in stock.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('else', 'A1', 'adv.', 'In addition; besides; different.', 'yang lain', 'She completed the task else and without making any mistakes at all.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('email', 'A1', 'n., v.', 'To send a message electronically.', 'surel / email', 'The teacher gave a clear and thorough explanation about the email to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('end', 'A1', 'n., v.', 'To come or bring to a conclusion; to finish.', 'akhir / mengakhiri', 'The concept of end plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('enjoy', 'A1', 'v.', 'To take pleasure in.', 'menikmati', 'I hope you enjoy the concert tonight.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('enough', 'A1', 'det., pron., adv.', 'As much or as many as needed; sufficient.', 'cukup', 'They visited enough museum during their trip.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('euro', 'A1', 'n.', 'Person living or originating from Europe', 'euro', 'They had a very productive and engaging discussion about the euro during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('even', 'A1', 'adv.', 'Used to emphasize something unexpected; flat and smooth.', 'bahkan', 'She can''t even afford to buy a bus ticket to get to work.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('evening', 'A1', 'n.', 'The period of time at the end of the day.', 'malam / sore', 'The evening is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('event', 'A1', 'n.', 'An occurrence; something that happens.', 'acara / peristiwa', 'He wrote a comprehensive and detailed report about the event for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ever', 'A1', 'adv.', 'At any time; always.', 'pernah', 'Please read the instructions ever before you start working on the assignment.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('every', 'A1', 'det.', 'Each one of a group; all the members of a group.', 'setiap', 'She gave every reason for being late today.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('everybody', 'A1', 'pron.', 'Every person; everyone.', 'semua orang', 'Everybody will handle the situation appropriately and carefully.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('everyone', 'A1', 'pron.', 'Every person.', 'semua orang', 'Everyone in the class successfully passed the difficult final exam this semester.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('everything', 'A1', 'pron.', 'All things; all.', 'semuanya', 'Please tell me everything about your exciting and wonderful trip to beautiful Bali.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('exam', 'A1', 'n.', 'The act of examining.', 'ujian', 'The concept of exam plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('example', 'A1', 'n.', 'A thing illustrating a rule.', 'contoh', 'The teacher gave a clear and thorough explanation about the example to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('excited', 'A1', 'adj.', 'Very enthusiastic and eager.', 'bersemangat / gembira', 'The weather today is quite excited compared to yesterday when it was much nicer outside.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('exciting', 'A1', 'adj.', 'Causing great enthusiasm and eagerness.', 'menarik / menggembirakan', 'Her presentation about the topic was very exciting and everyone in the audience found it engaging and informative.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('exercise', 'A1', 'n., v.', 'To do physical activity for health or training.', 'olahraga / latihan', 'He wrote a comprehensive and detailed report about the exercise for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('expensive', 'A1', 'adj.', 'Costing a lot of money; high-priced.', 'mahal', 'That designer handbag is too expensive for me to afford right now.');
