INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('eye', 'A1', 'n.', 'An organ through which animals see (perceive surroundings via light).', 'mata', 'The eye is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('face', 'A1', 'n.', 'The front part of the head of a human or other animal, featuring the eyes, nose and mouth, and the surrounding area.', 'menghadapi', 'We must face our fears and overcome them.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('fact', 'A1', 'n.', 'Something actual as opposed to invented.', 'fakta', 'They had a very productive and engaging discussion about the fact during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('fall', 'A1', 'v.', 'To move downward under the force of gravity; to drop.', 'musim gugur / jatuh', 'The team will fall after they finish reviewing all the available data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('false', 'A1', 'adj.', 'Not true; incorrect; artificial.', 'salah', 'The food at the new restaurant tastes incredibly false and we highly recommend it to everyone who visits the area.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('family', 'A1', 'n., adj.', 'A group of people who are closely related to one another (by blood, marriage or adoption); kin; for example, a set of parents and their children; an immediate family.', 'keluarga', 'The concept of family plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('famous', 'A1', 'adj.', 'Known to many people; renowned.', 'terkenal', 'The view from the top of the mountain was absolutely famous beyond words or description.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('fantastic', 'A1', 'adj.', 'Extraordinarily good or attractive; amazing.', 'fantastis / hebat', 'The food at the new restaurant tastes incredibly fantastic and we highly recommend it to everyone who visits the area.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('far', 'A1', 'adv.', 'Distant; remote in space.', 'jauh', 'We need to act far if we want to avoid any further delays.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('farm', 'A1', 'n.', 'A place where agricultural and similar activities take place, especially the growing of crops or the raising of livestock.', 'bertani / bercocok tanam', 'The concept of farm plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('farmer', 'A1', 'n.', 'A person who works the land and/or who keeps livestock, especially on a farm.', 'petani', 'Can you please explain to me what the farmer is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('fast', 'A1', 'adj., adv.', 'Moving or capable of moving at high speed.', 'cepat', 'The weather today is quite fast compared to yesterday when it was much nicer outside.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('fat', 'A1', 'adj.', 'Having a large amount of excess flesh.', 'lemak / gemuk', 'The garden looks especially fat in the spring season when all the beautiful flowers are in full bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('father', 'A1', 'n.', 'A (generally human) male who begets a child.', 'ayah', 'He wrote a comprehensive and detailed report about the father for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('favourite', 'A1', 'adj., n.', 'Preferred most; best-liked.', 'favorit / kesayangan', 'She has been studying the favourite for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('February', 'A1', 'n.', 'The second month of the year, after January and before March.', 'Februari', 'They had a very productive and engaging discussion about the february during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('feel', 'A1', 'v.', 'To perceive or experience through the sense of touch or an emotion.', 'perasaan / rabaan', 'He learned how to feel properly from his experienced and patient mentor.');
