INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('festival', 'A1', 'n.', 'An event or community gathering, usually staged by a local community, which centers on some theme, sometimes on some unique aspect of the community.', 'festival', 'They had a very productive and engaging discussion about the festival during the team meeting yesterday afternoon that lasted for over an hour.');
