INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('flat', 'A1', 'n.', 'Level and smooth; without curves; not high.', 'datar', 'I found an insightful article about the flat in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('flight', 'A1', 'n.', 'The act of flying.', 'penerbangan', 'Can you please explain to me what the flight is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('floor', 'A1', 'n.', 'The interior bottom or surface of a house or building; the supporting surface of a room.', 'lantai', 'They had a very productive and engaging discussion about the floor during the team meeting yesterday afternoon that lasted for over an hour.');
