INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('fly', 'A1', 'v.', 'To move through the air using wings.', 'lalat / terbang', 'Can you please fly this task for me? I would really appreciate your help.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('follow', 'A1', 'v.', 'To come after; to go behind; to obey.', 'mengikuti', 'The children followed the teacher into the classroom quietly.');
