INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('Friday', 'A1', 'n.', 'The day of the week after Thursday and before Saturday.', 'Jumat', 'Can you please explain to me what the friday is and why it is considered so important and significant in this particular context?');
