INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('friendly', 'A1', 'adj.', 'Kind and pleasant; not hostile.', 'ramah', 'The garden looks especially friendly in the spring season when all the beautiful flowers are in full bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('from', 'A1', 'prep.', 'Indicating the point where something starts or originates.', 'dari', 'The post office is from the bank and the supermarket building.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('front', 'A1', 'n., adj.', 'The foremost part of something; the side that faces forward.', 'depan', 'I read a very interesting article about the front in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('fruit', 'A1', 'n.', '(often in the plural) In general, a product of plant growth useful to man or animals.', 'buah', 'He wrote a comprehensive and detailed report about the fruit for his final project submission and presentation to the class.');
