INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('October', 'A1', 'n.', 'The tenth month of the year, after September and before November.', 'Oktober', 'I found an insightful article about the october in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('of', 'A1', 'prep.', 'Expressing the relationship between a part and a whole.', 'dari', 'He hid of the curtain so that nobody could see him hiding there.');
