INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('week', 'A1', 'n.', 'A period of seven days.', 'minggu', 'He wrote a comprehensive and detailed report about the week for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('weekend', 'A1', 'n.', 'Saturday and Sunday; the end of the week.', 'akhir pekan', 'I found an insightful article about the weekend in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('welcome', 'A1', 'exclam., v., adj.', 'Gladly received; a greeting upon arrival.', 'sambutan', 'Welcome, what a beautiful day it is outside!');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('well', 'A1', 'adv., adj., exclam.', 'In a good or satisfactory way; in good health.', 'dengan baik', 'She speaks English very well and fluently.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('west', 'A1', 'n., adj., adv.', 'One of the four principal compass points, specifically 270°, conventionally directed to the left on maps; the direction of the setting sun at an equinox, abbreviated as W.', 'barat', 'Can you please explain to me what the west is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('what', 'A1', 'pron./det.', 'Asking for information about something; the thing that.', 'apa', 'What is the person who won the competition this year.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('when', 'A1', 'adv., pron., conj.', 'At what time; at or during which.', 'kapan', 'He when agreed to help us with the project.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('where', 'A1', 'adv., conj.', 'In or to what place; at which.', 'di mana', 'She completed the task where and without making any mistakes at all.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('which', 'A1', 'pron./det.', 'Asking for information about one or more choices.', 'yang mana', 'Which is the person who won the competition this year.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('white', 'A1', 'adj., n.', 'The color/colour of snow or milk; the colour of light containing equal amounts of all visible wavelengths.', 'putih', 'Can you please explain to me what the white is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('who', 'A1', 'pron.', 'What person or people; the person that.', 'siapa', 'Who is the person who won the competition this year.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('why', 'A1', 'adv.', 'For what reason; on what basis.', 'mengapa / kenapa', 'She answered the question why and with great confidence.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wife', 'A1', 'n.', 'A married woman, especially in relation to her spouse.', 'istri', 'They had a very productive and engaging discussion about the wife during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('will', 'A1', 'modal v.', 'Expressing the future tense; to wish or intend.', 'keinginan / wasiat', 'I will help you with that if you need my assistance.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('win', 'A1', 'v.', 'To be successful in a contest.', 'kemenangan', 'They decided to win together as a team to achieve their shared common goal.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('window', 'A1', 'n.', 'The inedible parts of a grain-producing plant.', 'jendela', 'I read a very interesting article about the window in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wine', 'A1', 'n.', 'An alcoholic beverage made by fermenting the juice of grapes.', 'anggur', 'I read a very interesting article about the wine in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('winter', 'A1', 'n.', 'Traditionally the fourth of the four seasons, typically regarded as being from December 23 to March 20 in continental regions of the Northern Hemisphere or the months of June, July and August in the Southern Hemisphere. It is the time when the sun is lowest in the sky, resulting in short days, and the time of year with the lowest atmospheric temperatures for the region.', 'musim dingin', 'Can you please explain to me what the winter is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('with', 'A1', 'prep.', 'Accompanied by; having; using.', 'dengan', 'I went to the cinema with my best friend last night to watch a movie.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('without', 'A1', 'prep.', 'In the absence of; not having; lacking.', 'tanpa', 'They drove without the tunnel to get to the other side of the mountain.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('woman', 'A1', 'n.', 'An adult female human.', 'wanita / perempuan', 'I read a very interesting article about the woman in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wonderful', 'A1', 'adj.', 'Extremely good; marvelous; delightful.', 'luar biasa / indah', 'The food at the new restaurant tastes incredibly wonderful and we highly recommend it to everyone who visits the area.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('word', 'A1', 'n.', 'A unit of language consisting of one or more spoken sounds.', 'kata', 'The concept of word plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('work', 'A1', 'v., n.', 'To do a job or task; labor; occupation.', 'bekerja / pekerjaan', 'The teacher gave a clear and thorough explanation about the work to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('worker', 'A1', 'n.', 'A person who works; an employee.', 'pekerja', 'The teacher gave a clear and thorough explanation about the worker to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('world', 'A1', 'n.', 'The earth and all its countries and people.', 'dunia', 'They had a very productive and engaging discussion about the world during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('would', 'A1', 'modal v.', 'Expressing conditional or polite requests; past of will.', 'akan / mau', 'I would help you with that if you need my assistance.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('write', 'A1', 'v.', 'To mark letters or words on a surface.', 'menulis', 'They watched the instructor carefully write with great skill and precision.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('writer', 'A1', 'n.', 'A person who writes books or articles.', 'penulis', 'The teacher gave a clear and thorough explanation about the writer to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('writing', 'A1', 'n.', 'The activity or skill of writing.', 'menulis / tulisan', 'She has a deep interest in learning more about the writing and understanding its importance in our daily lives and how it affects us all in various ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wrong', 'A1', 'adj.', 'Not correct or true; mistaken.', 'salah', 'The food at the new restaurant tastes incredibly wrong and we highly recommend it to everyone who visits the area.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('yeah', 'A1', 'exclam.', 'Expressing joy, celebration, glee, etc.', 'ya', 'Yeah, what a beautiful day it is outside!');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('year', 'A1', 'n.', 'A period of 365 days; twelve months.', 'tahun', 'The teacher gave a clear and thorough explanation about the year to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('yellow', 'A1', 'adj., n.', 'The colour of gold, butter, or a lemon; the colour obtained by mixing green and red light, or by subtracting blue from white light.', 'kuning', 'The yellow is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('yes', 'A1', 'exclam.', 'Used to give an affirmative response.', 'ya', 'Yes! I did not expect to see you here today!');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('yesterday', 'A1', 'adv., n.', 'The day before today; on the day before.', 'kemarin', 'I went to the cinema yesterday to watch a new movie with my friends and I really enjoyed it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('you', 'A1', 'pron.', 'Used to refer to the person or people being addressed.', 'kamu / Anda', 'The manager spoke to you about the new project details.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('young', 'A1', 'adj.', 'Having lived for only a short time.', 'muda', 'The garden looks especially young in the spring season when all the beautiful flowers are in full bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('your', 'A1', 'det.', 'Belonging to or connected with the person being addressed.', 'milik kamu', 'Is this your pen or does it belong to someone else?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('yourself', 'A1', 'pron.', 'Used as the reflexive form of you.', 'dirimu sendiri', 'Please help yourself to some more food from the buffet table.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ability', 'A2', 'n.', 'Suitableness.', 'kemampuan', 'She has a natural ability to connect with people and make them feel comfortable and at ease.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('able', 'A2', 'adj.', 'Having the power, skill, or means to do something.', 'mampu', 'She is able to speak three different languages fluently and without any accent.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('abroad', 'A2', 'adv.', 'Countries or lands abroad.', 'luar negeri', 'She is planning to study abroad in England for one year to improve her English language skills and experience a different culture.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('accept', 'A2', 'v.', 'To receive, especially with a consent, with favour, or with approval.', 'menerima', 'She decided to accept the job offer because the salary was very attractive.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('accident', 'A2', 'n.', 'An unexpected event with negative consequences occurring without the intention of the one suffering the consequences.', 'kecelakaan', 'There was a serious car accident on the highway this morning but fortunately no one was killed or seriously injured.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('according to', 'A2', 'prep.', 'As stated or reported by someone or something.', 'menurut', 'According to the weather forecast it will rain today.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('achieve', 'A2', 'v.', 'To succeed in something, now especially in academic performance.', 'mencapai', 'She worked very hard to achieve her goals and dreams in life.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('act', 'A2', 'v.', 'To take action; to do something; to perform a role.', 'bertindak', 'We need to act quickly to solve this problem before it gets worse.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('active', 'A2', 'adj.', 'Engaging in physical activity; busy; lively.', 'aktif', 'She leads a very active lifestyle and exercises at the gym every single day.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('actually', 'A2', 'adv.', '(modal) In act or in fact; really; in truth; positively.', 'sebenarnya', 'Actually I think you might be mistaken about that.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('adult', 'A2', 'adj.', 'Fully grown; characteristic of an adult.', 'dewasa', 'The museum offers a special discounted ticket price for adults on weekends.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('advantage', 'A2', 'n.', 'Any condition, circumstance, opportunity or means, particularly favorable to success, or to any desired end.', 'keuntungan', 'One of the main advantages of living in a big city is having access to many different job opportunities.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('adventure', 'A2', 'n.', 'The encountering of risks; a bold undertaking, in which dangers are likely to be encountered, and the issue is staked upon unforeseen events; a daring feat.', 'petualangan', 'She has been studying the adventure for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('advertise', 'A2', 'v.', 'To give (especially public) notice of (something); to announce publicly.', 'mengiklankan', 'She needs to advertise before the deadline to avoid any penalties or problems.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('advertisement', 'A2', 'n.', 'A commercial solicitation designed to sell some commodity, service or similar.', 'iklan', 'They had a very productive and engaging discussion about the advertisement during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('advertising', 'A2', 'n.', 'Communication whose purpose is to influence potential customers about products and services.', 'periklanan', 'He wrote a comprehensive and detailed report about the advertising for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('affect', 'A2', 'v.', 'To influence or alter.', 'mempengaruhi', 'The bad weather will affect our travel plans and may cause some delays.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('after', 'A2', 'conj., adv.', 'In the time following; later than.', 'setelah', 'We went for a nice long walk in the park together after having our dinner.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('against', 'A2', 'prep.', 'In a contrary direction to.', 'melawan / terhadap', 'They drove against the tunnel to get to the other side of the mountain.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ah', 'A2', 'exclam.', 'Used to express surprise, pleasure, or realization.', 'ah', 'Ah, what a beautiful day it is outside!');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('airline', 'A2', 'n.', 'A company that operates aircraft for passenger transport.', 'maskapai penerbangan', 'I found an insightful article about the airline in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('alive', 'A2', 'adj.', 'Having life; living; not dead.', 'hidup', 'After the serious car accident she was just grateful and happy to be alive and well.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('all', 'A2', 'adv.', 'The whole quantity or extent of; every one of.', 'semua', 'All of the students in the class must complete and submit the assignment before the deadline.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('all right', 'A2', 'adj./adv., exclam.', 'Good; in acceptable, if not excellent condition.', 'baik-baik saja', 'Her presentation about the topic was very all right and everyone in the audience found it engaging and informative.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('allow', 'A2', 'v.', 'To permit; to let happen.', 'mengizinkan', 'The school rules do not allow students to use their phones during class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('almost', 'A2', 'adv.', 'Not quite; very nearly.', 'hampir', 'She almost missed the early morning bus because she had accidentally slept through her alarm clock and woke up late.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('alone', 'A2', 'adj./adv.', 'Without others; by oneself.', 'sendirian', 'The new policy has been alone for the company and its employees according to the feedback that we have received so far from various stakeholders.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('along', 'A2', 'prep., adv.', 'Moving in a constant direction on a path.', 'sepanjang', 'The restaurant is located along the main street in the town center.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('already', 'A2', 'adv.', 'Before the time in question; as early as now.', 'sudah', 'He already agreed to help us with the project.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('alternative', 'A2', 'n.', 'One of two or more possibilities; available as another option.', 'alternatif', 'We need to find an alternative solution to the problem.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('although', 'A2', 'conj.', 'In spite of the fact that; even though.', 'meskipun', 'Although she was very tired she stayed up late to finish her homework and complete her assignment.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('among', 'A2', 'prep.', 'In the middle of; surrounded by; in a group.', 'di antara', 'The restaurant is located among the main street in the town center.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('amount', 'A2', 'n.', 'The total quantity or sum of something.', 'berjumlah', 'He wrote a comprehensive and detailed report about the amount for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ancient', 'A2', 'adj.', 'Belonging to the very distant past; very old.', 'kuno', 'The garden looks especially ancient in the spring season when all the beautiful flowers are in full bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ankle', 'A2', 'n.', 'The joint connecting the foot to the leg.', 'pergelangan kaki', 'She has been studying the ankle for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('any', 'A2', 'adv.', 'One or some of a thing, no matter how much or how many.', 'apa pun', 'Do you have any questions at all about the lesson that we just finished covering today in class?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('anybody', 'A2', 'pron.', 'Any one out of an indefinite number of persons; anyone; any person.', 'siapa pun', 'Anybody is responsible for making the final decision on this matter.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('any more', 'A2', 'adv.', '(in negative or interrogative constructions) From a given time onwards; longer, again.', 'lagi', 'The meeting went any more according to the plan and schedule.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('anyway', 'A2', 'adv.', 'Regardless; anyhow.', 'bagaimanapun', 'She answered the question anyway and with great confidence.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('anywhere', 'A2', 'adv., pron.', 'In or at any location or an unknown location.', 'di mana pun', 'I cannot find my missing keys anywhere in the entire house.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('app', 'A2', 'n.', 'An application (program), especially a small one designed for a mobile device.', 'aplikasi', 'The teacher gave a clear and thorough explanation about the app to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('appear', 'A2', 'v.', 'To come or be in sight; to be in view; to become visible.', 'muncul', 'The sun finally appeared from behind the clouds after the rain stopped.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('appearance', 'A2', 'n.', 'The act of appearing or coming into sight; the act of becoming visible to the eye.', 'penampilan', 'I read a very interesting article about the appearance in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('apply', 'A2', 'v.', 'To lay or place; to put (one thing to another)', 'melamar', 'She decided to apply for the job because it matched her skills.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('architect', 'A2', 'n.', 'A professional who designs buildings or other structures, or who prepares plans and superintends construction.', 'arsitek', 'She has been studying the architect for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('architecture', 'A2', 'n.', 'The art and science of designing and managing the construction of buildings and other structures, particularly if they are well proportioned and decorated.', 'arsitektur', 'I read a very interesting article about the architecture in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('argue', 'A2', 'v.', 'To show grounds for concluding (that); to indicate, imply.', 'berdebat', 'The couple sometimes argue about small things but they always make up.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('argument', 'A2', 'n.', 'A fact or statement used to support a proposition; a reason.', 'argumen / perdebatan', 'The argument is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('army', 'A2', 'n.', 'A large, highly organized military force, concerned mainly with ground (rather than air or naval) operations.', 'tentara', 'I found an insightful article about the army in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('arrange', 'A2', 'v.', 'To set up; to organize; to put into an orderly sequence or arrangement.', 'mengatur', 'She will arrange a meeting with the client for next Tuesday afternoon.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('arrangement', 'A2', 'n.', 'The act of arranging.', 'susunan / pengaturan', 'She has a deep interest in learning more about the arrangement and understanding its importance in our daily lives and how it affects us all in various ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('as', 'A2', 'adv., conj.', 'Used to indicate that something happens at the same time as something else.', 'sebagai', 'She works full time as a dedicated and passionate teacher at the local elementary school in our neighborhood.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('asleep', 'A2', 'adj.', 'In a state of sleep.', 'tertidur', 'The garden looks especially asleep in the spring season when all the beautiful flowers are in full bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('assistant', 'A2', 'n., adj.', 'Someone who is present; a bystander, a witness.', 'asisten', 'The assistant is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('athlete', 'A2', 'n.', 'A person who is proficient in sports.', 'atlet', 'The athlete is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('attack', 'A2', 'n., v.', 'To act aggressively against; to harm.', 'menyerang', 'The army decided to attack the enemy position under cover of darkness.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('attend', 'A2', 'v.', 'To be present at.', 'menghadiri', 'She attends English class every Tuesday evening after work.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('attention', 'A2', 'n., exclam.', 'Focus; notice.', 'perhatian', 'Please pay close attention to the important instructions that I am about to give you right now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('attractive', 'A2', 'adj.', 'Causing attraction; having the quality of attracting by inherent force.', 'menarik', 'The view from the top of the mountain was absolutely attractive beyond words or description.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('audience', 'A2', 'n.', 'The people who watch or listen to a performance.', 'penonton', 'The audience applauded enthusiastically after the performance.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('author', 'A2', 'n.', 'The originator or creator of a work, especially of a literary composition.', 'penulis', 'The author signed copies of his book for fans.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('available', 'A2', 'adj.', 'Such as one may avail oneself of; capable of being used for the accomplishment of a purpose.', 'tersedia', 'The product is available in three different colors.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('average', 'A2', 'adj., n.', 'The typical amount; ordinary; usual.', 'rata-rata', 'The concept of average plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('avoid', 'A2', 'v.', 'To try not to meet or communicate with (a person); to shun', 'menghindari', 'You should avoid eating too much sugar to stay healthy.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('award', 'A2', 'n.', 'A prize or honor.', 'penghargaan', 'She received an award for her outstanding performance.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('awful', 'A2', 'adj.', 'Very bad; terrible; unpleasant.', 'mengerikan', 'The weather was awful; it rained the entire day.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('back', 'A2', 'adj.', 'In the opposite direction from the front; toward the rear.', 'kembali', 'I will call you back later this evening after I get home from work and have dinner.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('background', 'A2', 'n.', 'The part of a scene behind the main subject; a person''s education or experience.', 'latar belakang', 'She comes from a humble family background.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('badly', 'A2', 'adv.', 'Ill, unwell.', 'dengan buruk', 'The meeting went badly according to the plan and schedule.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bar', 'A2', 'n.', 'A solid, more or less rigid object of metal or wood with a uniform cross-section smaller than its length.', 'menghalangi', 'I read a very interesting article about the bar in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('baseball', 'A2', 'n.', 'A sport played with a bat and ball between two teams of nine players.', 'bisbol', 'She has been studying the baseball for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('based', 'A2', 'adj.', 'Founded on', 'berbasis', 'He gave a remarkably based performance on stage that impressed everyone in the audience.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('basketball', 'A2', 'n.', 'A sport in which two opposing teams of five players strive to put a ball through a hoop.', 'bola basket', 'She has a deep interest in learning more about the basketball and understanding its importance in our daily lives and how it affects us all in various ways.');
