INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cook', 'A2', 'n.', 'A person who prepares food.', 'memasak', 'My mother taught me how to cook delicious traditional meals.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cooker', 'A2', 'n.', 'A device for heating food, a stove.', 'kompor', 'The concept of cooker plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('copy', 'A2', 'n., v.', 'The result of copying; an identical duplicate of an original.', 'salinan', 'Please make a copy of this important legal document and keep it in a safe place for your records and future reference.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('corner', 'A2', 'n.', 'The point where two converging lines meet; an angle, either external or internal.', 'sudut', 'I found an insightful article about the corner in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('correctly', 'A2', 'adv.', 'In a correct manner.', 'dengan benar', 'She answered the question correctly and with great confidence.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('count', 'A2', 'v.', 'To determine the total number of; to recite numbers in order.', 'menghitung', 'Can you please count from one to ten in English for me so I can hear your pronunciation?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('couple', 'A2', 'n.', 'Two partners in a romantic or sexual relationship.', 'pasangan', 'A friendly young couple just recently moved into the house that is located right next door to ours in the neighborhood.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cover', 'A2', 'v.', 'To place something over or upon, as to conceal or protect.', 'menutupi', 'Please remember to cover the cooking pot with a tight fitting lid while the rice is boiling and simmering on the stove.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('crazy', 'A2', 'adj.', 'Mentally unstable; very enthusiastic.', 'gila', 'That incredibly fast and thrilling roller coaster ride at the amusement park was absolutely crazy and insane and I loved every single second of it!');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('creative', 'A2', 'adj.', 'Involving the use of imagination to create something new.', 'kreatif', 'The view from the top of the mountain was absolutely creative beyond words or description.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('credit', 'A2', 'n.', 'Reliance on the truth of something said or done; faith; trust.', 'kredit', 'She decided to purchase the expensive laptop on credit and will be paying it off in convenient monthly installments over the course of the next year.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('crime', 'A2', 'n.', 'An illegal act.', 'kejahatan', 'The local police department is working extremely hard and diligently to effectively reduce the overall rate of crime in the neighborhood and surrounding area.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('criminal', 'A2', 'n.', 'A person who commits a crime.', 'penjahat', 'The dangerous criminal was finally arrested by the police and taken to court to face justice and be held accountable for his serious crimes.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cross', 'A2', 'v., n.', 'To go across; a symbol of Christianity.', 'menyeberang', 'Please remember to always look both ways before you attempt to cross the busy street to ensure your safety.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('crowd', 'A2', 'n.', 'A group of people congregated or collected into a close body without order.', 'kerumunan', 'A huge excited crowd of devoted fans gathered together to watch the popular band perform their live concert at the stadium.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('crowded', 'A2', 'adj.', 'To press forward; to advance by pushing.', 'penuh sesak', 'The public subway train is always extremely crowded and packed full of people during the busy morning and evening rush hours.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cry', 'A2', 'v.', 'To shed tears as an expression of distress or emotion.', 'menangis', 'The baby started to cry because she was hungry and tired.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cupboard', 'A2', 'n.', 'A storage cabinet.', 'lemari', 'All the clean plates bowls and cups are stored neatly organized in the kitchen cupboard next to the sink.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('curly', 'A2', 'adj.', 'Having curls; shaped in curves or spiral.', 'keriting', 'The garden looks especially curly in the spring season when all the beautiful flowers are in full bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cycle', 'A2', 'n., v.', 'An interval of space or time in which one set of events or phenomena is completed.', 'siklus / bersepeda', 'She has been studying the cycle for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('daily', 'A2', 'adj.', 'Done, happening, or published every day.', 'harian / setiap hari', 'Reading the morning newspaper and enjoying a hot cup of coffee is an essential part of my daily morning routine that I follow without fail every single day.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('danger', 'A2', 'n.', 'Exposure to likely harm; peril.', 'bahaya', 'The prominent warning sign clearly posted at the entrance of the construction site warns everyone of the potential danger that lies ahead and advises caution.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dark', 'A2', 'n.', 'Having an absolute or (more often) relative lack of light.', 'gelap', 'The room was so extremely dark and pitch black that I could not see anything at all in front of me even with my eyes wide open and adjusted to the darkness.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('data', 'A2', 'n.', '(plural: data) A measurement of something on a scale understood by both the recorder (a person or device) and the reader (another person or device). The scale is arbitrarily defined, such as from 1 to 10 by ones, 1 to 100 by 0.1, or simply true or false, on or off, yes, no, or maybe, etc.', 'data', 'The technology company systematically collects and analyzes large amounts of valuable user data in order to continuously improve the quality of its products and services.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dead', 'A2', 'adj.', 'No longer alive; not living.', 'mati', 'The neglected plant in the corner of the room is unfortunately completely dead because I completely forgot to water it regularly for several weeks while I was away on a long trip.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('deal', 'A2', 'v.', 'To handle or manage; to distribute.', 'kesepakatan', 'The two companies successfully signed a major business deal worth several million dollars after months of intense negotiation and discussion.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dear', 'A2', 'exclam.', 'Regarded with deep affection; expensive.', 'sayang', 'My dear friend I miss you so very much and I hope to see you again very soon.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('death', 'A2', 'n.', 'The cessation of life and all associated processes; the end of an organism''s existence as an entity independent from its environment and its return to an inert, nonliving state.', 'kematian', 'The sudden and unexpected news of his untimely death came as a tremendous shock to everyone who knew him and loved him deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('decision', 'A2', 'n.', 'The act of deciding.', 'keputusan', 'Making the right and well informed decision is not always an easy or straightforward thing to do especially when the stakes are high.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('deep', 'A2', 'adj.', 'Going far down; of great depth.', 'dalam', 'The calm lake is surprisingly very deep in the middle so swimmers are strongly advised to exercise caution and stay safe at all times while swimming and enjoying the water.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('definitely', 'A2', 'adv.', 'Without question and beyond doubt.', 'pasti', 'I will definitely be there on time for tomorrow morning important meeting without any doubt.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('degree', 'A2', 'n.', 'A stage of proficiency or qualification in a course of study, now especially an award bestowed by a university or, in some countries, a college, as a certification of academic achievement. (In the United States, can include secondary schools.)', 'gelar', 'She successfully earned a prestigious degree in economics from one of the top ranked universities in the entire country after four years of hard work and dedicated study.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dentist', 'A2', 'n.', 'A medical doctor who specializes in dentistry.', 'dokter gigi', 'The concept of dentist plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('department', 'A2', 'n.', 'A part, portion, or subdivision.', 'departemen', 'She currently works as a senior analyst in the marketing department of a large successful multinational corporation.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('depend', 'A2', 'v.', 'To be determined by or contingent on.', 'tergantung', 'Whether or not we decide to go to the beautiful beach this weekend depends entirely on the unpredictable weather forecast and conditions at that time.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('desert', 'A2', 'n.', '(usually in the plural) That which is deserved or merited; a just punishment or reward', 'gurun', 'The vast Sahara Desert is widely known and recognized as the largest hot desert in the entire world covering a massive area across the northern region of the African continent.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('designer', 'A2', 'n.', 'A person who designs something, or who designs things as a profession.', 'perancang / desainer', 'The talented and creative fashion designer recently launched her own successful clothing line which has become very popular among fashion enthusiasts.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('destroy', 'A2', 'v.', 'To damage beyond use or repair.', 'menghancurkan', 'The incredibly powerful and devastating earthquake that struck the region suddenly and without warning destroyed thousands of buildings homes and other structures in a matter of mere seconds causing widespread damage and destruction.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('detective', 'A2', 'n.', '(law enforcement) A police officer who looks for evidence as part of solving a crime; an investigator.', 'detektif', 'The brilliant and determined detective worked tirelessly around the clock for weeks on end to solve the complex and baffling murder case that had everyone in the department completely stumped and confused.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('develop', 'A2', 'v.', 'To change with a specific direction, progress.', 'mengembangkan', 'The technology company plans to invest heavily in research and development to develop innovative new software products that will revolutionize the industry.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('device', 'A2', 'n.', 'Any piece of equipment made for a particular purpose, especially a mechanical or electrical one.', 'perangkat', 'All passengers are kindly requested and reminded to please turn off all their portable electronic devices before the aircraft takes off from the runway for safety reasons.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('diary', 'A2', 'n.', 'A daily log of experiences, especially those of the writer.', 'buku harian', 'She makes it a consistent habit to write in her personal private diary every single night right before she goes to sleep to record her thoughts feelings and experiences from the day.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('differently', 'A2', 'adv.', '(manner) In a different way.', 'secara berbeda', 'The meeting went differently according to the plan and schedule.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('digital', 'A2', 'adj.', 'Relating to or using technology; expressed as digits.', 'digital', 'We need to find a more digital approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('direct', 'A2', 'adj.', 'Without stopping or changing direction; straight.', 'langsung', 'This particular route that I am showing you on the map is the most direct and fastest way to get to the airport from here without any unnecessary detours or delays.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('direction', 'A2', 'n.', 'A course along which something moves.', 'arah', 'According to the GPS navigation system the car was unfortunately heading in the completely wrong direction and we needed to turn around immediately to correct our course and get back on the right path to reach our intended destination.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('director', 'A2', 'n.', 'A person who manages.', 'direktur', 'The company director officially announced her plans to retire at the end of this year after dedicating over thirty years of her life to working for the organization and helping it grow and succeed.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('disagree', 'A2', 'v.', 'To have a different opinion.', 'tidak setuju', 'I must respectfully and politely disagree with your conclusion and analysis of this particular situation because I believe there are several important factors that you may have overlooked or not fully considered in your assessment.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('disappear', 'A2', 'v.', 'To vanish.', 'menghilang', 'The talented magician performed an incredible trick on stage and made the white rabbit completely disappear right before the amazed audiences very eyes in an instant leaving everyone in utter shock and disbelief at what they had just witnessed.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('disaster', 'A2', 'n.', 'An unexpected natural or man-made catastrophe of substantial extent causing significant physical damage or destruction, loss of life or sometimes permanent change to the natural environment.', 'bencana', 'The massive earthquake that struck the coastal region was a truly terrible and devastating natural disaster that caused immense destruction widespread damage and heartbreaking loss of life on an unimaginable scale.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('discover', 'A2', 'v.', 'To find something new.', 'menemukan', 'A team of dedicated scientists recently discovered an entirely new and previously unknown species of colorful frog living deep in the remote unexplored regions of the dense Amazon rainforest.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('discovery', 'A2', 'n.', 'The act of discovering.', 'penemuan', 'The groundbreaking discovery of the powerful antibiotic penicillin by Alexander Fleming back in the year 1928 has saved countless millions of lives around the world since then and revolutionized the entire field of modern medicine.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('discussion', 'A2', 'n.', 'Conversation or debate concerning a particular topic.', 'diskusi / pembahasan', 'The lively and productive team discussion about the important budget proposal lasted for well over two hours and generated many valuable ideas and suggestions that will be incorporated into the final plan.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('disease', 'A2', 'n.', 'An illness.', 'penyakit', 'Practicing good hygiene habits such as regularly and thoroughly washing your hands with soap and clean water is one of the most effective ways to help prevent the easy spread of infectious diseases and stay healthy.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('distance', 'A2', 'n.', 'The amount of space between two points, usually geographical points, usually (but not necessarily) measured along a straight line.', 'jarak', 'The approximate distance between the two major cities is about two hundred kilometers which would take around three hours to travel by car depending on the traffic conditions on the main highway.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('divorced', 'A2', 'adj.', 'Cut off, or separated.', 'bercerai', 'The results of the experiment were divorced according to the researchers who conducted the study and analyzed the collected data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('document', 'A2', 'n.', 'An original or official paper used as the basis, proof, or support of anything else, including any writing, book, or other instrument conveying information pertinent to such proof or support.', 'mendokumentasikan', 'I read a very interesting article about the document in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('double', 'A2', 'adj., det., pron., v.', 'Twice as much or as many; made of two parts.', 'dua kali lipat', 'It is important to know when to double and when to wait for the right moment.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('download', 'A2', 'v., n.', 'A file transfer to the local computer.', 'mengunduh', 'I read a very interesting article about the download in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('downstairs', 'A2', 'adj.', 'On or to a lower floor of a building.', 'di lantai bawah', 'Her presentation about the topic was very downstairs and everyone in the audience found it engaging and informative.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('drama', 'A2', 'n.', 'A composition, normally in prose, telling a story and intended to be represented by actors impersonating the characters and speaking the dialogue', 'drama', 'He wrote a comprehensive and detailed report about the drama for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('drawing', 'A2', 'n.', 'To move or develop something.', 'menggambar / gambar', 'The drawing is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dream', 'A2', 'n., v.', 'Imaginary events seen in the mind while sleeping.', 'bermimpi', 'She dreams of becoming a famous singer one day.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('drive', 'A2', 'n.', 'Motivation to do or achieve something', 'dorongan / semangat', 'I found an insightful article about the drive in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('driving', 'A2', 'n.', 'To provide an impetus for motion or other physical change, to move an object by means of the provision of force thereto.', 'mengemudi', 'She has been studying the driving for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('drop', 'A2', 'v.', 'To fall in droplets', 'menjatuhkan', 'Be careful not to drop the fragile glass vase.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('drug', 'A2', 'n.', 'A substance used to treat an illness, relieve a symptom, or modify a chemical process in the body for a specific purpose.', 'obat', 'She has been studying the drug for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dry', 'A2', 'adj., v.', 'Not wet; without moisture.', 'kering', 'The clothes will dry quickly outside under the hot bright sun today.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('earn', 'A2', 'v.', 'To gain (success, reward, recognition) through applied effort or work.', 'menghasilkan / memperoleh', 'It is important to know when to earn and when to wait for the right moment.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('earth', 'A2', 'n.', 'The third planet of the Solar System; the world upon which humans live.', 'bumi', 'The earth is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('easily', 'A2', 'adv.', 'Comfortably, without discomfort or anxiety.', 'dengan mudah', 'We need to act easily if we want to avoid any further delays.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('education', 'A2', 'n.', 'The process of imparting knowledge, skill and judgment.', 'pendidikan', 'Education is the most powerful weapon that you can use to change the world for the better.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('effect', 'A2', 'n.', 'The result or outcome of a cause.', 'efek / akibat', 'They had a very productive and engaging discussion about the effect during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('either', 'A2', 'det./pron., adv.', 'One or the other of two; each of two.', 'salah satu', 'He needs either help with the difficult project.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('electric', 'A2', 'adj.', 'Relating to or powered by electricity.', 'listrik', 'The weather today is quite electric compared to yesterday when it was much nicer outside.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('electrical', 'A2', 'adj.', 'Relating to or concerned with electricity.', 'kelistrikan', 'The movie we watched last night was surprisingly electrical and exceeded all of our expectations by a wide margin.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('electricity', 'A2', 'n.', 'Originally, a property of amber and certain other nonconducting substances to attract lightweight material when rubbed, or the cause of this property; now understood to be a phenomenon caused by the distribution and movement of charged subatomic particles and their interaction with the electromagnetic field.', 'listrik', 'She has been studying the electricity for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('electronic', 'A2', 'adj.', 'Using or relating to devices that operate with electricity.', 'elektronik', 'The food at the new restaurant tastes incredibly electronic and we highly recommend it to everyone who visits the area.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('employ', 'A2', 'v.', 'To give work to someone.', 'mempekerjakan', 'The company employs over five thousand people worldwide.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('employee', 'A2', 'n.', 'An individual who provides labor to a company or another person.', 'karyawan', 'She has been studying the employee for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('employer', 'A2', 'n.', 'A person or organization that employs.', 'pemberi kerja / majikan', 'The employer is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('empty', 'A2', 'adj.', 'Containing nothing; not filled or occupied.', 'mengosongkan', 'The new policy has been empty for the company and its employees according to the feedback that we have received so far from various stakeholders.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ending', 'A2', 'n.', 'A termination or conclusion.', 'akhir', 'The teacher gave a clear and thorough explanation about the ending to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('energy', 'A2', 'n.', 'The capacity for doing work.', 'energi', 'They had a very productive and engaging discussion about the energy during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('engine', 'A2', 'n.', 'A machine that produces power.', 'mesin', 'She has a deep interest in learning more about the engine and understanding its importance in our daily lives and how it affects us all in various ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('engineer', 'A2', 'n.', 'A person who is qualified or professionally engaged in any branch of engineering.', 'insinyur', 'She has been studying the engineer for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('enormous', 'A2', 'adj.', 'Very large in size, amount, or extent.', 'sangat besar', 'We need to find a more enormous approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('enter', 'A2', 'v.', 'To come or go into.', 'masuk', 'Please knock before you enter the room.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('environment', 'A2', 'n.', 'The surroundings of, and influences on, a particular item of interest.', 'lingkungan', 'I read a very interesting article about the environment in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('equipment', 'A2', 'n.', 'The act of equipping, or the state of being equipped, as for a voyage or expedition.', 'peralatan', 'She has been studying the equipment for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('error', 'A2', 'n.', 'The state, quality, or condition of being wrong.', 'kesalahan', 'Can you please explain to me what the error is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('especially', 'A2', 'adv.', '(manner) In a special manner; specially.', 'terutama', 'I absolutely love all different kinds of fruits but especially sweet ripe mangoes when they are in season.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('essay', 'A2', 'n.', '(authorship) A written composition of moderate length, exploring a particular issue or subject.', 'esai', 'They had a very productive and engaging discussion about the essay during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('everyday', 'A2', 'adj.', 'Happening or used every day; ordinary.', 'sehari-hari', 'The movie we watched last night was surprisingly everyday and exceeded all of our expectations by a wide margin.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('everywhere', 'A2', 'adv.', 'In or to all locations under discussion.', 'di mana-mana', 'I have looked everywhere for my missing glasses but I still cannot find them anywhere at all.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('evidence', 'A2', 'n.', 'Facts or observations presented in support of an assertion.', 'bukti', 'They had a very productive and engaging discussion about the evidence during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('exact', 'A2', 'adj.', 'Precise and accurate; not approximate.', 'tepat / persis', 'The movie we watched last night was surprisingly exact and exceeded all of our expectations by a wide margin.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('exactly', 'A2', 'adv.', 'In an exact manner; precisely; accurately.', 'tepatnya / persis', 'She spoke exactly during the important meeting last week.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('excellent', 'A2', 'adj.', 'Extremely good; outstanding.', 'sangat baik', 'The food at that new restaurant is absolutely excellent and very reasonably priced.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('except', 'A2', 'prep.', 'Not including; apart from.', 'kecuali', 'She sat except her best friend during the long flight to Europe.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('exist', 'A2', 'v.', 'To have actual being.', 'ada', 'Do aliens really exist somewhere in the universe?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('expect', 'A2', 'v.', 'To think something will happen.', 'mengharapkan', 'I expect the package to arrive by Friday.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('experience', 'A2', 'n.', 'The effect upon the judgment or feelings produced by any event, whether witnessed or participated in; personal and direct impressions as contrasted with description or fancies; personal acquaintance; actual enjoyment or suffering.', 'pengalaman', 'She gained valuable work experience during her internship at the company.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('experiment', 'A2', 'n.', 'A test under controlled conditions made to either demonstrate a known truth, examine the validity of a hypothesis, or determine the efficacy of something previously untried.', 'bereksperimen', 'I found an insightful article about the experiment in a magazine that I was reading last night before I went to sleep.');
