INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('traditional', 'A2', 'adj.', 'Relating to tradition; conventional; established.', 'tradisional', 'Her presentation about the topic was very traditional and everyone in the audience found it engaging and informative.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('train', 'A2', 'v.', 'To practice an ability.', 'melatih', 'He is training to become a professional athlete.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('trainer', 'A2', 'n.', 'A person who trains another; a coach.', 'pelatih', 'They had a very productive and engaging discussion about the trainer during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('training', 'A2', 'n.', 'Action of the verb to train.', 'pelatihan / latihan', 'I found an insightful article about the training in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('transport', 'A2', 'n.', 'An act of transporting; conveyance.', 'mengangkut / membawa', 'I found an insightful article about the transport in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('traveller', 'A2', 'n.', 'A member of a particular nomadic ethnic minority in Ireland, the Pavee.', 'pelancong / wisatawan', 'He wrote a comprehensive and detailed report about the traveller for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('trouble', 'A2', 'n.', 'A distressing or dangerous situation.', 'mengganggu / merepotkan', 'I read a very interesting article about the trouble in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('truck', 'A2', 'n.', 'A small wheel or roller, specifically the wheel of a gun carriage.', 'truk', 'He wrote a comprehensive and detailed report about the truck for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('twin', 'A2', 'n., adj.', 'Either of two people (or, less commonly, animals) who shared the same uterus at the same time; one who was born at the same birth as a sibling.', 'kembar', 'She has been studying the twin for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('typical', 'A2', 'adj.', 'Having the usual characteristics of a group; representative.', 'khas / umum', 'The movie we watched last night was surprisingly typical and exceeded all of our expectations by a wide margin.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('underground', 'A2', 'adj., adv.', 'An underground railway, especially for mass transit of people in urban areas.', 'bawah tanah', 'We need to find a more underground approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('understanding', 'A2', 'n.', 'To grasp a concept fully and thoroughly, especially (of words, statements, art, etc.) to be aware of the meaning of and (of people) to be aware of the intent of.', 'pemahaman', 'The concept of understanding plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('unfortunately', 'A2', 'adv.', 'By bad luck.', 'sayangnya', 'Unfortunately the store was already closed when we arrived.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('unhappy', 'A2', 'adj.', 'Not happy; sad; dissatisfied.', 'tidak bahagia / sedih', 'The results of the experiment were unhappy according to the researchers who conducted the study and analyzed the collected data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('uniform', 'A2', 'n.', 'A distinctive outfit that serves to identify members of a group.', 'seragam', 'The concept of uniform plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('unit', 'A2', 'n.', 'A particular, minute unit of mass, defined differently for different substances, but so that varying substances of the same general type have the property that one international unit of the one has the same effect on the human body as one international unit of the other.', 'unit', 'I read a very interesting article about the unit in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('united', 'A2', 'adj.', 'Joined together for a common purpose.', 'bersatu', 'The food at the new restaurant tastes incredibly united and we highly recommend it to everyone who visits the area.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('unusual', 'A2', 'adj.', 'Not usual; uncommon; remarkable.', 'tidak biasa', 'The garden looks especially unusual in the spring season when all the beautiful flowers are in full bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('upstairs', 'A2', 'adj.', 'On an upper floor.', 'di lantai atas', 'Her presentation about the topic was very upstairs and everyone in the audience found it engaging and informative.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('use', 'A2', 'n.', 'The act of using.', 'penggunaan', 'They had a very productive and engaging discussion about the use during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('used to', 'A2', 'modal v.', 'Used to show that something happened regularly or existed in the past but does not now.', 'dulu / biasa', 'You used to finish your homework before you go out to play.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('user', 'A2', 'n.', 'A person who uses a product or service.', 'pengguna', 'The teacher gave a clear and thorough explanation about the user to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('usual', 'A2', 'adj.', 'Happening most often; normal; customary.', 'biasa', 'The view from the top of the mountain was absolutely usual beyond words or description.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('valley', 'A2', 'n.', 'An elongated depression between hills or mountains, often with a river flowing through it.', 'lembah', 'He wrote a comprehensive and detailed report about the valley for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('van', 'A2', 'n.', 'A covered vehicle used for carrying goods or people, usually roughly cuboid in shape, longer and higher than a car but smaller than a truck/lorry.', 'van / mobil boks', 'I found an insightful article about the van in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('variety', 'A2', 'n.', 'The quality of being varied; diversity.', 'variasi / keragaman', 'The concept of variety plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
