INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('view', 'A2', 'n.', 'The ability to see something; a sight or prospect.', 'melihat / memandang', 'They had a very productive and engaging discussion about the view during the team meeting yesterday afternoon that lasted for over an hour.');
