INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wait', 'A2', 'n.', 'A delay.', 'penantian / menunggu', 'The teacher gave a clear and thorough explanation about the wait to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('war', 'A2', 'n.', 'A state of armed conflict between countries or groups.', 'perang', 'They had a very productive and engaging discussion about the war during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wash', 'A2', 'n.', 'The process or an instance of washing or being washed by water or other liquid.', 'cucian / mencuci', 'The concept of wash plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('washing', 'A2', 'n.', 'The act of cleaning something with water.', 'mencuci', 'Can you please explain to me what the washing is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wave', 'A2', 'n.', 'To move back and forth repeatedly and somewhat loosely.', 'melambai', 'She has been studying the wave for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('weak', 'A2', 'adj.', 'Lacking physical strength or power.', 'lemah', 'The view from the top of the mountain was absolutely weak beyond words or description.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('web', 'A2', 'n.', 'The World Wide Web.', 'web / jaringan', 'The web is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wedding', 'A2', 'n.', 'A marriage ceremony.', 'pernikahan', 'I found an insightful article about the wedding in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('weight', 'A2', 'n.', '(physical) Matter, material.', 'berat / bobot', 'They had a very productive and engaging discussion about the weight during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('welcome', 'A2', 'n.', 'Gladly received; a greeting upon arrival.', 'sambutan', 'The welcome is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wet', 'A2', 'adj.', 'Covered with water; not dry.', 'basah', 'The food at the new restaurant tastes incredibly wet and we highly recommend it to everyone who visits the area.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wheel', 'A2', 'n.', 'A circular device capable of rotating on its axis, facilitating movement or transportation or performing labour in machines.', 'roda', 'The concept of wheel plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
