INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('whole', 'A2', 'adj.', 'All of something; entire; not divided.', 'keseluruhan', 'The results of the experiment were whole according to the researchers who conducted the study and analyzed the collected data.');
