INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wild', 'A2', 'adj.', 'The undomesticated state of a wild animal', 'liar', 'The weather today is quite wild compared to yesterday when it was much nicer outside.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wind1', 'A2', 'n.', 'Real or perceived movement of atmospheric air usually caused by convection or differences in air pressure.', 'angin', 'I read a very interesting article about the wind1 in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('winner', 'A2', 'n.', 'One who has won or often wins.', 'pemenang', 'She has a deep interest in learning more about the winner and understanding its importance in our daily lives and how it affects us all in various ways.');
