INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wood', 'A2', 'n.', 'The substance making up the central part of the trunk and branches of a tree. Used as a material for construction, to manufacture various items, etc. or as fuel.', 'kayu', 'He wrote a comprehensive and detailed report about the wood for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wooden', 'A2', 'adj.', 'Made of wood; stiff and awkward.', 'dari kayu / kayu', 'The results of the experiment were wooden according to the researchers who conducted the study and analyzed the collected data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('working', 'A2', 'adj.', 'Having paid employment; functioning.', 'bekerja', 'The weather today is quite working compared to yesterday when it was much nicer outside.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('worried', 'A2', 'adj.', 'Feeling anxious or concerned.', 'khawatir', 'The weather today is quite worried compared to yesterday when it was much nicer outside.');
