INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('worse', 'A2', 'adj.', 'Less good; more bad or severe.', 'lebih buruk', 'Her presentation about the topic was very worse and everyone in the audience found it engaging and informative.');
