INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('zero', 'A2', 'number', 'The number 0; no quantity or number.', 'nol', 'There are zero students in the classroom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('absolutely', 'B1', 'adv.', 'In an absolute or unconditional manner; utterly, positively, wholly.', 'benar-benar', 'The food at that highly recommended restaurant is absolutely delicious and I highly recommend it to everyone.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('academic', 'B1', 'adj.', '(usually capitalized) A follower of Plato, a Platonist.', 'akademis', 'She had a very successful academic career and graduated at the top of her class with high honors.');
