INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('account', 'B1', 'n.', 'A registry of pecuniary transactions; a written or printed statement of business dealings or debts and credits, and also of other things subjected to a reckoning or review.', 'akun', 'The bank accountant will review your account details.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('achievement', 'B1', 'n.', 'The act of achieving or performing; a successful performance; accomplishment', 'pencapaian / prestasi', 'I found an insightful article about the achievement in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('act', 'B1', 'n.', 'Something done, a deed.', 'bertindak', 'We need to act quickly to solve this problem before it gets worse.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ad', 'B1', 'n.', 'Advertisement.', 'iklan', 'The teacher gave a clear and thorough explanation about the ad to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('addition', 'B1', 'n.', 'The act of adding anything.', 'penambahan / tambahan', 'The addition is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('admire', 'B1', 'v.', 'To be amazed at; to view with surprise; to marvel at.', 'mengagumi', 'I really admire your dedication and hard work.');
