INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('agent', 'B1', 'n.', 'One who exerts power, or has the power to act', 'agen', 'The teacher gave a clear and thorough explanation about the agent to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('agreement', 'B1', 'n.', 'An understanding between entities to follow a specific course of conduct.', 'persetujuan / perjanjian', 'The concept of agreement plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
