INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('alarm', 'B1', 'n.', 'A summons to arms, as on the approach of an enemy.', 'alarm', 'The fire alarm went off in the middle of the night.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('album', 'B1', 'n.', 'A collection of recordings issued as a single item.', 'album', 'She has been studying the album for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('alcohol', 'B1', 'n.', 'A colorless liquid found in drinks such as beer and wine.', 'alkohol', 'The alcohol is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
