INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('apart', 'B1', 'adv.', '(Used after a noun or in the predicate) Exceptional, distinct.', 'terpisah', 'The two close friends decided to live apart after sharing a house together for several years.');
