INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('application', 'B1', 'n.', 'The act of applying or laying on, in a literal sense', 'aplikasi / lamaran', 'The concept of application plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
