INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('contrast', 'B1', 'n., v.', 'A difference in lightness, brightness and/or hue between two colours that makes them more or less distinguishable.', 'kontras / perbedaan', 'The concept of contrast plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('convenient', 'B1', 'adj.', 'Suitable for one''s needs; easy to use.', 'nyaman / praktis', 'He gave a remarkably convenient performance on stage that impressed everyone in the audience.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('convince', 'B1', 'v.', 'To make someone believe, or feel sure about something, especially by using logic, argument or evidence.', 'meyakinkan', 'She managed to convince her parents to let her study abroad.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cool', 'B1', 'v.', 'Having a slightly low temperature; mildly cold.', 'sejuk / dingin', 'The water in the mountain stream is wonderfully cool and incredibly refreshing to drink on a hot summer day.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('costume', 'B1', 'n.', 'A style of dress, including garments, accessories and hairstyle, especially as characteristic of a particular country, period or people.', 'kostum', 'He wrote a comprehensive and detailed report about the costume for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cottage', 'B1', 'n.', 'A small house.', 'pondok', 'The cottage is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cotton', 'B1', 'n.', 'Gossypium, a genus of plant used as a source of cotton fiber.', 'katun', 'This comfortable and breathable shirt is made of one hundred percent pure cotton fabric so it feels very soft and gentle against the skin.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('count', 'B1', 'n.', 'The act of counting or tallying a quantity.', 'menghitung', 'Can you count from one to ten in English for me?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('countryside', 'B1', 'n.', 'A rural area, or the rural part of a larger area.', 'pedesaan', 'We took a long scenic drive through the peaceful green countryside to enjoy and appreciate the beautiful natural scenery and landscapes.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('court', 'B1', 'n.', 'An enclosed space; a courtyard; an uncovered area shut in by the walls of a building, or by different buildings; also, a space opening from a street and nearly surrounded by houses; a blind alley.', 'pengadilan / lapangan', 'The court is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cover', 'B1', 'n.', 'A lid.', 'menutupi', 'Cover the pot with a lid while the rice is cooking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('covered', 'B1', 'adj.', 'Having a layer over the surface; protected.', 'tertutup', 'Her presentation about the topic was very covered and everyone in the audience found it engaging and informative.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cream', 'B1', 'adj.', 'The fatty part of milk; a thick liquid or semi-solid cosmetic.', 'krem / krim', 'We need to find a more cream approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('criminal', 'B1', 'adj.', 'A person who commits a crime.', 'penjahat', 'The dangerous criminal was finally arrested by the police and taken to court to face justice and be held accountable for his serious crimes.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cruel', 'B1', 'adj.', 'Willfully causing pain.', 'kejam', 'It is considered cruel and inhumane to mistreat or neglect innocent animals in any way shape or form.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cultural', 'B1', 'adj.', 'Relating to the ideas, customs, and social behavior of a society.', 'budaya', 'The garden looks especially cultural in the spring season when all the beautiful flowers are in full bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('currency', 'B1', 'n.', 'The system of money used in a country.', 'mata uang', 'The currency is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('current', 'B1', 'adj.', 'The generally unidirectional movement of a gas or fluid.', 'saat ini', 'What is the current local time in Tokyo Japan right now at this moment?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('currently', 'B1', 'adv.', 'At the present time.', 'saat ini', 'Everything happened currently as we had expected and planned.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('curtain', 'B1', 'n.', 'A piece of cloth covering a window, bed, etc. to offer privacy and keep out light.', 'tirai / gorden', 'She gently pulled the curtain open wide to let the warm morning sunlight stream into the room and brighten it up.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('custom', 'B1', 'n.', 'Frequent repetition of the same behavior; way of behavior common to many; ordinary manner; habitual practice; method of doing, living or behaving.', 'kebiasaan / adat', 'It is a well known local custom and tradition in many Asian countries to politely remove your shoes before entering someones home as a sign of respect and courtesy.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cut', 'B1', 'n.', 'The act of cutting.', 'memotong / mengiris', 'Please be extremely careful and cautious not to accidentally cut yourself with that very sharp kitchen knife while you are chopping the vegetables for dinner.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('daily', 'B1', 'adv.', 'Done, happening, or published every day.', 'harian', 'Reading the newspaper every morning is an important part of my daily routine.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('damage', 'B1', 'n., v.', 'Injury or harm; the condition or measure of something not being intact.', 'kerusakan', 'The powerful and destructive storm unfortunately caused very significant and extensive damage to the farmers valuable crops and agricultural fields across the entire region.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('deal', 'B1', 'n.', 'A division, a portion, a share.', 'menangani', 'How do you usually deal with stressful situations at work?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('decade', 'B1', 'n.', 'A group, set, or series of ten , particularly:', 'dekade / dasawarsa', 'Over the course of the past decade technology has changed and evolved dramatically and transformed nearly every aspect of our daily lives in countless ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('decorate', 'B1', 'v.', 'To furnish with decorations.', 'menghias / mendekorasi', 'Our family always comes together to decorate the beautiful Christmas tree with colorful lights ornaments and tinsel every single December without fail as part of our cherished and beloved annual tradition.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('deep', 'B1', 'adv.', 'Going far down; of great depth.', 'dalam', 'The lake is very deep in the middle so please be careful when you are swimming in it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('define', 'B1', 'v.', 'To determine with precision', 'mendefinisikan', 'Could you please clearly define what the complex term sustainability actually means in simple and easy to understand language?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('definite', 'B1', 'adj.', '(grammar) A word or phrase that designates a specified or identified person or entity.', 'pasti', 'She urgently needs a definite and concrete answer from you by the end of this week at the very latest.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('definition', 'B1', 'n.', 'A statement of the meaning of a word or word group or a sign or symbol (dictionary definitions).', 'definisi', 'If you come across any unfamiliar or confusing words while reading the textbook you should look up their precise definition in a reliable dictionary to gain a better understanding of their meaning.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('deliver', 'B1', 'v.', 'To set free from restraint or danger.', 'mengantar', 'The friendly reliable postman delivers the mail to our house every single morning bright and early around nine o clock.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('departure', 'B1', 'n.', 'The act of departing or something that has departed.', 'keberangkatan', 'All passengers are kindly requested to check in for their flight at least two full hours before the scheduled departure time.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('despite', 'B1', 'prep.', 'Disdain, contemptuous feelings, hatred.', 'meskipun', 'Despite the fact that it was raining heavily and steadily outside the entire time they courageously decided to continue playing their football match anyway and refused to give up or stop playing.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('destination', 'B1', 'n.', 'The act of destining or appointing.', 'tujuan', 'Our final travel destination for this years summer vacation trip is the beautiful and romantic city of Paris in France which we are both incredibly excited to visit and explore together.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('determine', 'B1', 'v.', 'To set the boundaries or limits of.', 'menentukan', 'We urgently need to first determine and identify the underlying root cause of the persistent problem before we can even begin to think about finding an effective solution to it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('determined', 'B1', 'adj.', 'Decided', 'bertekad', 'She is absolutely determined and fully committed to finishing the marathon race successfully no matter what challenges or difficulties she may face along the way.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('development', 'B1', 'n.', 'The process of developing; growth, directed change.', 'pembangunan / perkembangan', 'The rapid development of renewable and sustainable energy technologies and sources is absolutely crucial for the future health and well being of our planet and all the living creatures that inhabit it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('diagram', 'B1', 'n.', 'A plan, drawing, sketch or outline to show how something works, or show the relationships between the parts of a whole.', 'diagram', 'The helpful diagram provided in the instruction manual clearly and simply explains how the complex engine system actually works step by step.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('diamond', 'B1', 'n.', 'A glimmering glass-like mineral that is an allotrope of carbon in which each atom is surrounded by four others in the form of a tetrahedron.', 'berlian / intan', 'He got down on one knee and presented her with a beautiful sparkling diamond engagement ring as he asked her the most important question of his life.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('difficulty', 'B1', 'n.', 'The state of being difficult, or hard to do.', 'kesulitan', 'She slowly and carefully managed to climb the steep and treacherous mountain path with great difficulty and determination relying on her strength and willpower every step of the way.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('direct', 'B1', 'v., adv.', 'Without stopping or changing direction; straight.', 'langsung', 'This is the most direct route to the airport from here without any detours.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('directly', 'B1', 'adv.', 'In a direct way; immediately.', 'secara langsung', 'We need to act directly if we want to avoid any further delays.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dirt', 'B1', 'n.', 'Soil or earth.', 'kotoran / tanah', 'She has been studying the dirt for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('disadvantage', 'B1', 'n.', 'A weakness or undesirable characteristic; a con.', 'kerugian / kekurangan', 'One of the main disadvantages and drawbacks of living in a big crowded city is the constant high level of noise pollution from traffic construction and other urban activities that can be very stressful and bothersome for many people.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('disappointed', 'B1', 'adj.', 'Sad because expectations were not met.', 'kecewa', 'She was deeply disappointed and upset with herself when she saw her final exam results which were much lower than what she had been hoping for and expecting after all her hard work and diligent preparation throughout the semester.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('disappointing', 'B1', 'adj.', 'Failing to meet expectations; unsatisfying.', 'mengecewakan', 'The highly anticipated film adaptation of the popular book was unfortunately very disappointing and did not live up to the high expectations of most fans of the original novel who had been eagerly waiting to see it come to life on the big screen.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('discount', 'B1', 'n.', 'A reduction in price.', 'memberi diskon', 'I found an insightful article about the discount in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dislike', 'B1', 'v., n.', 'To find unpleasant; a feeling of not liking something.', 'tidak menyukai / kebencian', 'The dislike is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('divide', 'B1', 'v.', 'To split or separate', 'membagi', 'Please divide the pizza into eight equal slices.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('documentary', 'B1', 'n.', 'A film, TV program, publication etc. which presents a social, political, scientific or historical subject in a factual or informative manner.', 'dokumenter', 'The teacher gave a clear and thorough explanation about the documentary to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('donate', 'B1', 'v.', 'To make a donation; to give away something of value to support or contribute towards a cause or for the benefit of another.', 'menyumbang', 'They decided to donate together as a team to achieve their shared common goal.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('double', 'B1', 'adv.', 'Twice as much or as many; made of two parts.', 'dua kali lipat', 'She completed the task double and without making any mistakes at all.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('doubt', 'B1', 'n., v.', 'Disbelief or uncertainty (about something); a particular instance of such disbelief or uncertainty.', 'meragukan', 'I doubt that he will arrive on time given the heavy traffic.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dressed', 'B1', 'adj.', 'To fit out with the necessary clothing; to clothe, put clothes on (something or someone).', 'berpakaian', 'Her presentation about the topic was very dressed and everyone in the audience found it engaging and informative.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('drop', 'B1', 'n.', 'A small quantity of liquid, just large enough to hold its own round shape via surface tension, especially one that falls from a source of liquid.', 'menjatuhkan', 'Be careful not to drop the fragile glass vase.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('drum', 'B1', 'n.', 'A percussive musical instrument spanned with a thin covering on at least one end for striking, forming an acoustic chamber, affecting what materials are used to make it; a membranophone.', 'drum / gendang', 'Can you please explain to me what the drum is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('drunk', 'B1', 'adj.', 'To consume (a liquid) through the mouth.', 'mabuk', 'The garden looks especially drunk in the spring season when all the beautiful flowers are in full bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('due', 'B1', 'adj.', 'Expected or required to happen; owed.', 'jatuh tempo', 'The assignment is due next Monday morning and must be submitted on time.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dust', 'B1', 'n.', 'Fine particles', 'debu', 'She has been studying the dust for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('duty', 'B1', 'n.', 'That which one is morally or legally obligated to do.', 'tugas / kewajiban', 'Can you please explain to me what the duty is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('earthquake', 'B1', 'n.', 'A shaking of the ground, caused by volcanic activity or movement around geologic faults.', 'gempa bumi', 'The teacher gave a clear and thorough explanation about the earthquake to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('eastern', 'B1', 'adj.', 'Situated in or facing the east.', 'timur', 'We need to find a more eastern approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('economic', 'B1', 'adj.', 'Relating to the economy or economics.', 'ekonomi', 'The results of the experiment were economic according to the researchers who conducted the study and analyzed the collected data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('economy', 'B1', 'n.', 'Effective management of a community or system, or especially its resources.', 'ekonomi', 'The teacher gave a clear and thorough explanation about the economy to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('edge', 'B1', 'n.', 'The boundary line of a surface.', 'tepi / ujung', 'The teacher gave a clear and thorough explanation about the edge to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('editor', 'B1', 'n.', 'A person who edits or makes changes to documents.', 'editor / penyunting', 'The concept of editor plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('educate', 'B1', 'v.', 'To instruct or train', 'mendidik', 'The campaign aims to educate people about healthy eating.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('educated', 'B1', 'adj.', 'To instruct or train', 'berpendidikan', 'We need to find a more educated approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('educational', 'B1', 'adj.', 'Providing knowledge or instruction; relating to education.', 'pendidikan / edukatif', 'The garden looks especially educational in the spring season when all the beautiful flowers are in full bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('effective', 'B1', 'adj.', 'Successful in producing a desired or intended result.', 'efektif', 'We need to find a more effective approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('effectively', 'B1', 'adv.', 'In an efficient or effective manner; with powerful effect.', 'secara efektif', 'We need to act effectively if we want to avoid any further delays.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('effort', 'B1', 'n.', 'The work involved in performing an activity; exertion.', 'usaha / upaya', 'They had a very productive and engaging discussion about the effort during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('election', 'B1', 'n.', 'A process of choosing a leader, members of parliament, councillors or other representatives by popular vote.', 'pemilihan / pemilu', 'I read a very interesting article about the election in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('element', 'B1', 'n.', 'One of the simplest or essential parts or principles of which anything consists, or upon which the constitution or fundamental powers of anything are based.', 'elemen / unsur', 'She has been studying the element for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('embarrassed', 'B1', 'adj.', 'Feeling ashamed or shy.', 'malu', 'The weather today is quite embarrassed compared to yesterday when it was much nicer outside.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('embarrassing', 'B1', 'adj.', 'Causing someone to feel awkward or ashamed.', 'memalukan', 'The weather today is quite embarrassing compared to yesterday when it was much nicer outside.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('emergency', 'B1', 'n.', 'An urgent situation.', 'darurat', 'The concept of emergency plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('emotion', 'B1', 'n.', 'A person''s internal state of being and involuntary physiological response to an object or a situation, based on or tied to physical state and sensory data.', 'emosi / perasaan', 'The concept of emotion plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('employment', 'B1', 'n.', 'The state of having paid work.', 'pekerjaan / lapangan kerja', 'The teacher gave a clear and thorough explanation about the employment to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('empty', 'B1', 'v.', 'Containing nothing; not filled or occupied.', 'mengosongkan', 'They decided to empty together as a team to achieve their shared common goal.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('encourage', 'B1', 'v.', 'To mentally support; to motivate, give courage, hope or spirit.', 'mendorong', 'My teacher always encourages me to do my best.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('enemy', 'B1', 'n.', 'Someone who is hostile to, feels hatred towards, opposes the interests of, or intends injury to someone else.', 'musuh', 'They had a very productive and engaging discussion about the enemy during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('engaged', 'B1', 'adj.', 'Busy; formally promised to marry someone.', 'bertunangan / sibuk', 'He gave a remarkably engaged performance on stage that impressed everyone in the audience.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('engineering', 'B1', 'n.', 'The application of science to design and build structures.', 'teknik / rekayasa', 'I found an insightful article about the engineering in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('entertain', 'B1', 'v.', 'To amuse.', 'menghibur', 'She needs to entertain before the deadline to avoid any penalties or problems.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('entertainment', 'B1', 'n.', 'Amusement; shows.', 'hiburan', 'The entertainment is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('entrance', 'B1', 'n.', 'The action of entering, or going in.', 'pintu masuk', 'The main entrance to the museum is through the grand front gate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('entry', 'B1', 'n.', 'The act of entering.', 'pintu masuk / entri', 'I found an insightful article about the entry in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('environmental', 'B1', 'adj.', 'Relating to the natural environment.', 'lingkungan', 'Her presentation about the topic was very environmental and everyone in the audience found it engaging and informative.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('episode', 'B1', 'n.', 'An incident, action, or time period standing out by itself, but more or less connected with a complete series of events.', 'episode', 'They had a very productive and engaging discussion about the episode during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('equal', 'B1', 'adj., v.', 'The same in quantity, size, degree, or value.', 'sebanding / setara', 'They decided to equal together as a team to achieve their shared common goal.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('equally', 'B1', 'adv.', '(manner) In an equal manner; in equal shares or proportion; with equal and impartial justice; evenly', 'sama-sama / secara merata', 'The meeting went equally according to the plan and schedule.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('escape', 'B1', 'v., n.', 'The act of leaving a dangerous or unpleasant situation.', 'melarikan diri / kabur', 'They had a very productive and engaging discussion about the escape during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('essential', 'B1', 'adj.', 'Absolutely necessary; extremely important.', 'penting / esensial', 'The garden looks especially essential in the spring season when all the beautiful flowers are in full bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('eventually', 'B1', 'adv.', 'In the end; at some later time, especially after a long time, a series of problems, struggles, delays or setbacks.', 'akhirnya', 'After many years of hard work determination and perseverance she eventually achieved her dream of becoming a successful doctor.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('examine', 'B1', 'v.', 'To inspect closely.', 'memeriksa', 'The doctor examined the patient thoroughly before making a diagnosis.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('except', 'B1', 'conj.', 'Not including; apart from.', 'kecuali', 'She wanted to go to the party except she was feeling too tired to go out.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('exchange', 'B1', 'n., v.', 'To give and receive.', 'pertukaran / menukar', 'He wrote a comprehensive and detailed report about the exchange for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('excitement', 'B1', 'n.', 'The state of being excited.', 'kegembiraan', 'The excitement is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('exhibition', 'B1', 'n.', 'A public display.', 'pameran', 'He wrote a comprehensive and detailed report about the exhibition for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('expand', 'B1', 'v.', 'To become larger.', 'memperluas', 'The company plans to expand into international markets.');
