INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('odd', 'B1', 'adj.', 'Different from what is usual; strange.', 'aneh / ganjil', 'We need to find a more odd approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('official', 'B1', 'adj.', 'Approved by authority; formal and authorized.', 'pejabat / resmi', 'He gave a remarkably official performance on stage that impressed everyone in the audience.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('old-fashioned', 'B1', 'adj.', 'No longer modern or fashionable; outdated.', 'kuno / ketinggalan zaman', 'The results of the experiment were old-fashioned according to the researchers who conducted the study and analyzed the collected data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('once', 'B1', 'conj.', 'One time; on one single occasion; formerly.', 'begitu / ketika', 'We can eat at home tonight once go out to a restaurant instead.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('operation', 'B1', 'n.', 'The method by which a device performs its function.', 'operasi', 'She has been studying the operation for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('organized', 'B1', 'adj.', 'Of a person, characterised by efficient organization.', 'terorganisir / rapi', 'The results of the experiment were organized according to the researchers who conducted the study and analyzed the collected data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('organizer', 'B1', 'n.', 'A person who arranges the details of a public event.', 'penyelenggara', 'He wrote a comprehensive and detailed report about the organizer for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('original', 'B1', 'n.', 'First; earliest; not copied; unique.', 'asli / orisinal', 'He wrote a comprehensive and detailed report about the original for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('originally', 'B1', 'adv.', 'As it was in the beginning.', 'awalnya', 'She spoke originally during the important meeting last week.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ought', 'B1', 'modal v.', 'Property; possession', 'seharusnya', 'You ought finish your homework before you go out to play.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ours', 'B1', 'pron.', 'That which belongs to us; the possessive case of we, used without a following noun.', 'milik kami', 'This victory belongs to all of us because it is ours to celebrate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('outdoor', 'B1', 'adj.', '(in some African communities) To publicly display a child after it has been named', 'luar ruangan', 'We need to find a more outdoor approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('outdoors', 'B1', 'adv.', '(often preceded by "the") The environment outside of enclosed structures.', 'di luar ruangan', 'Everything happened outdoors as we had expected and planned.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('pack', 'B1', 'n.', 'A bundle made up and prepared to be carried; especially, a bundle to be carried on the back, but also a load for an animal, a bale.', 'mengemas', 'I need to pack my suitcase for the trip tomorrow.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('package', 'B1', 'n.', 'Something which is packed, a parcel, a box, an envelope.', 'mengemas', 'The concept of package plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('painful', 'B1', 'adj.', 'Causing physical or emotional pain.', 'menyakitkan', 'The movie we watched last night was surprisingly painful and exceeded all of our expectations by a wide margin.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('pale', 'B1', 'adj.', 'Light in color; having less color than usual.', 'pucat', 'The results of the experiment were pale according to the researchers who conducted the study and analyzed the collected data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('pan', 'B1', 'n.', 'A wide, flat receptacle used around the house, especially for cooking.', 'wajan / panci', 'She has been studying the pan for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('participate', 'B1', 'v.', 'To join in, to take part, to involve oneself (in something).', 'berpartisipasi', 'She needs to participate before the deadline to avoid any penalties or problems.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('particularly', 'B1', 'adv.', '(focus) Especially, extremely.', 'khususnya / terutama', 'Please read the instructions particularly before you start working on the assignment.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('pass', 'B1', 'n.', 'To go past or through; to move forward; to succeed in a test.', 'kartu izin / lulus', 'They had a very productive and engaging discussion about the pass during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('passion', 'B1', 'n.', 'Any great, strong, powerful emotion, especially romantic love or extreme hate.', 'gairah / hasrat', 'He wrote a comprehensive and detailed report about the passion for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('path', 'B1', 'n.', 'A trail for the use of, or worn by, pedestrians.', 'jalan setapak / jalur', 'The concept of path plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('payment', 'B1', 'n.', 'The act of paying.', 'pembayaran', 'The concept of payment plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('peaceful', 'B1', 'adj.', 'Free from disturbance; calm and quiet.', 'damai / tenteram', 'The new policy has been peaceful for the company and its employees according to the feedback that we have received so far from various stakeholders.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('percentage', 'B1', 'n.', 'The amount, number or rate of something, regarded as part of a total of 100; a part of a whole.', 'persentase', 'The percentage is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('perfectly', 'B1', 'adv.', 'With perfection.', 'dengan sempurna', 'The beautiful dress fits her perfectly and she looks absolutely stunning and elegant in it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('performance', 'B1', 'n.', 'The act of performing; carrying into execution or action; execution; achievement; accomplishment; representation by action.', 'penampilan / pertunjukan', 'I found an insightful article about the performance in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('personally', 'B1', 'adv.', 'In a personal manner.', 'secara pribadi', 'The meeting went personally according to the plan and schedule.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('persuade', 'B1', 'v.', 'To successfully convince (someone) to agree to, accept, or do something, usually through reasoning and verbal influence.', 'membujuk', 'She persuaded her friend to join the gym with her.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('photographer', 'B1', 'n.', 'One who takes photographs, typically as an occupation.', 'fotografer', 'She has been studying the photographer for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('photography', 'B1', 'n.', 'The art and technology of producing images on photosensitive surfaces, and its digital counterpart.', 'fotografi', 'The photography is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('pin', 'B1', 'n., v.', 'A needle without an eye (usually) made of drawn-out steel wire with one end sharpened and the other flattened or rounded into a head, used for fastening.', 'peniti / pin', 'I found an insightful article about the pin in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('pipe', 'B1', 'n.', 'Meanings relating to a wind instrument.', 'pipa', 'She has a deep interest in learning more about the pipe and understanding its importance in our daily lives and how it affects us all in various ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('place', 'B1', 'v.', 'A particular position or location.', 'menempatkan', 'Please place the books neatly on the shelf.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('planning', 'B1', 'n.', 'To design (a building, machine, etc.).', 'perencanaan', 'She has been studying the planning for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('pleasant', 'B1', 'adj.', 'Giving a sense of happy satisfaction; enjoyable.', 'menyenangkan', 'We had a very pleasant evening together at the beach watching the sunset.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('pleasure', 'B1', 'n.', 'A state of being pleased or contented; gratification.', 'kesenangan', 'The pleasure is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('plenty', 'B1', 'pron.', 'A plentiful supply; enough or more than enough.', 'banyak / cukup', 'The teacher asked plenty to stay after class for a moment.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('plot', 'B1', 'n.', '(authorship) The course of a story, comprising a series of incidents which are gradually unfolded, sometimes by unexpected means.', 'merencanakan / mengatur', 'They had a very productive and engaging discussion about the plot during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('plus1', 'B1', 'prep.', 'And', 'plus / lebih', 'She walked plus1 the bridge to cross to the other side of the river.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('poem', 'B1', 'n.', 'A literary piece written in verse.', 'puisi', 'She has been studying the poem for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('poet', 'B1', 'n.', 'A person who writes poems.', 'penyair', 'I found an insightful article about the poet in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('poetry', 'B1', 'n.', 'Literature composed in verse or language exhibiting conscious attention to patterns and rhythm.', 'puisi', 'I read a very interesting article about the poetry in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('point', 'B1', 'v.', 'A discrete division of something.', 'menunjuk', 'She pointed at the map to show us the location.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('poison', 'B1', 'n., v.', 'A substance that is harmful or lethal to a living organism.', 'racun', 'She has a deep interest in learning more about the poison and understanding its importance in our daily lives and how it affects us all in various ways.');
