INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('policy', 'B1', 'n.', 'A principle of behaviour, conduct etc. thought to be desirable or necessary, especially as formally expressed by a government or other authoritative body.', 'kebijakan', 'The concept of policy plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('political', 'B1', 'adj.', 'Relating to the government or public affairs.', 'politik', 'We need to find a more political approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('politician', 'B1', 'n.', 'One engaged in politics, especially an elected or appointed government official.', 'politisi / politikus', 'The concept of politician plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('politics', 'B1', 'n.', 'A methodology and activities associated with running a government, an organization, or a movement.', 'politik', 'I found an insightful article about the politics in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('port', 'B1', 'n.', 'A place on the coast at which ships can shelter, or dock to load and unload cargo or passengers.', 'pelabuhan', 'I read a very interesting article about the port in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('portrait', 'B1', 'n.', 'A painting or other picture of a person, especially the head and shoulders.', 'potret', 'She has a deep interest in learning more about the portrait and understanding its importance in our daily lives and how it affects us all in various ways.');
