INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('pot', 'B1', 'n.', 'A flat-bottomed vessel (usually metal) used for cooking food.', 'panci / periuk', 'Can you please explain to me what the pot is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('pour', 'B1', 'v.', 'To cause liquid to flow from a container.', 'menuangkan', 'Please pour some water into the glass for me.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('poverty', 'B1', 'n.', 'The quality or state of being poor; lack of money', 'kemiskinan', 'She has been studying the poverty for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('powder', 'B1', 'n.', 'The fine particles which are the result of reducing dry substance by pounding, grinding, or triturating, or the result of decay; dust.', 'bubuk / bedak', 'She has been studying the powder for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
