INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('prayer', 'B1', 'n.', 'A religious petition.', 'doa', 'I read a very interesting article about the prayer in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('prediction', 'B1', 'n.', 'A statement of what will happen in the future.', 'prediksi / ramalan', 'They had a very productive and engaging discussion about the prediction during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('prepared', 'B1', 'adj.', 'Made ready or fit; willing to do something.', 'siap', 'We need to find a more prepared approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('presentation', 'B1', 'n.', 'A talk presenting something.', 'presentasi', 'He wrote a comprehensive and detailed report about the presentation for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('press', 'B1', 'n., v.', 'A device used to apply pressure to an item.', 'pers / menekan', 'The teacher gave a clear and thorough explanation about the press to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('pressure', 'B1', 'n.', 'Force applied; stress.', 'tekanan', 'The teacher gave a clear and thorough explanation about the pressure to help the students understand the concept better and more deeply.');
