INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('previous', 'B1', 'adj.', 'Existing or occurring before in time.', 'sebelumnya', 'The new policy has been previous for the company and its employees according to the feedback that we have received so far from various stakeholders.');
