INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('producer', 'B1', 'n.', 'An individual or organization that creates goods and services.', 'produsen', 'He wrote a comprehensive and detailed report about the producer for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('production', 'B1', 'n.', 'The act of producing, making or creating something.', 'produksi', 'He wrote a comprehensive and detailed report about the production for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('profession', 'B1', 'n.', 'A declaration of belief, faith or one''s opinion, whether genuine or pretended.', 'profesi', 'The profession is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
