INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('properly', 'B1', 'adv.', 'In a proper manner, appropriately, suitably; correctly, justifiably', 'dengan benar / tepat', 'She spoke properly during the important meeting last week.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('property', 'B1', 'n.', 'Something that is owned.', 'properti / milik', 'I read a very interesting article about the property in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('protest', 'B1', 'n., v.', 'A formal objection, especially one by a group.', 'protes', 'They had a very productive and engaging discussion about the protest during the team meeting yesterday afternoon that lasted for over an hour.');
