INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('qualification', 'B1', 'n.', 'A quality or skill.', 'kualifikasi', 'I read a very interesting article about the qualification in the newspaper this morning and it was quite informative and thought provoking.');
