INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('qualify', 'B1', 'v.', 'An instance of throwing and catching each prop at least twice.', 'memenuhi syarat', 'They decided to qualify together as a team to achieve their shared common goal.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('queue', 'B1', 'n., v.', 'A line of people waiting.', 'antrean / antre', 'He wrote a comprehensive and detailed report about the queue for his final project submission and presentation to the class.');
