INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('quotation', 'B1', 'n.', 'A fragment of a human expression that is repeated by somebody else. Most often a quotation is taken from literature or speech, but also scenes from a movie, elements of a painting, a passage of music, etc., may be quoted.', 'kutipan', 'The teacher gave a clear and thorough explanation about the quotation to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('quote', 'B1', 'v., n.', 'To repeat words from another source.', 'mengutip', 'They had a very productive and engaging discussion about the quote during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('race (people)', 'B1', 'n.', 'A group of people sharing physical characteristics.', 'ras / suku bangsa', 'I read a very interesting article about the race (people) in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('racing', 'B1', 'n.', 'To take part in a race (in the sense of a contest).', 'balapan', 'I found an insightful article about the racing in a magazine that I was reading last night before I went to sleep.');
