INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('water', 'B1', 'v.', 'To pour water on; to give water to.', 'air', 'Please remember to drink plenty of clean fresh water every single day to stay properly hydrated and healthy.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wave', 'B1', 'v.', 'To move one''s hand from side to side as a signal.', 'melambai', 'The team will wave after they finish reviewing all the available data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('weapon', 'B1', 'n.', 'A thing used for fighting.', 'senjata', 'They had a very productive and engaging discussion about the weapon during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('weigh', 'B1', 'v.', 'To measure the weight of someone or something.', 'menimbang', 'The package weighs about five kilograms.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('western', 'B1', 'adj.', 'Situated in or facing the west.', 'barat', 'He gave a remarkably western performance on stage that impressed everyone in the audience.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('whatever', 'B1', 'det./pron.', 'Anything that; no matter what.', 'apa pun', 'Please feel free to eat whatever you want from the menu because dinner is my treat tonight.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('whenever', 'B1', 'conj.', '(interrogative) When ever: emphatic form of when.', 'kapan pun', 'You can call me whenever you need any help or assistance with your homework or studies.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('whether', 'B1', 'conj.', 'Which of two.', 'apakah', 'I am truly not sure whether I should accept the job offer or not.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('while', 'B1', 'n.', 'An uncertain duration of time, a period of time.', 'sementara', 'She read an interesting book while patiently waiting for the bus to arrive at the bus stop.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('whole', 'B1', 'n.', 'All of something; entire; not divided.', 'keseluruhan', 'She has a deep interest in learning more about the whole and understanding its importance in our daily lives and how it affects us all in various ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('will', 'B1', 'n.', 'Expressing the future tense; to wish or intend.', 'keinginan / wasiat', 'They had a very productive and engaging discussion about the will during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('win', 'B1', 'n.', 'To be victorious in a contest; to gain as a result.', 'kemenangan', 'I found an insightful article about the win in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wing', 'B1', 'n.', 'An appendage of an animal''s (bird, bat, insect) body that enables it to fly; a similar fin at the side of a ray or similar fish', 'sayap', 'They had a very productive and engaging discussion about the wing during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('within', 'B1', 'prep.', 'In the context of which the present document or ruling is made.', 'dalam / di dalam', 'He walked within the room without making a single sound.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wonder', 'B1', 'v., n.', 'Something that causes amazement or awe; a marvel.', 'bertanya-tanya', 'I wonder what life would be like on another planet.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wool', 'B1', 'n.', 'The hair of the sheep, llama and some other ruminants.', 'wol', 'She has been studying the wool for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('worldwide', 'B1', 'adj., adv.', 'Spanning the world; global.', 'di seluruh dunia / mendunia', 'The results of the experiment were worldwide according to the researchers who conducted the study and analyzed the collected data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('worry', 'B1', 'n.', 'A strong feeling of anxiety.', 'kekhawatiran', 'I read a very interesting article about the worry in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('worse', 'B1', 'adv.', 'Less good; more bad or severe.', 'lebih buruk', 'They worked worse together to finish the project on time and within budget.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('worst', 'B1', 'adv.', 'The least good; most bad.', 'paling buruk', 'She completed the task worst and without making any mistakes at all.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('worth', 'B1', 'adj.', 'Having a value of; deserving of.', 'nilai / harga', 'The results of the experiment were worth according to the researchers who conducted the study and analyzed the collected data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('written', 'B1', 'adj.', 'Expressed in writing; recorded.', 'tertulis', 'The view from the top of the mountain was absolutely written beyond words or description.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wrong', 'B1', 'adv.', 'Not correct or true; mistaken.', 'salah', 'We need to act wrong if we want to avoid any further delays.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('yard', 'B1', 'n.', 'A small, usually uncultivated area adjoining or (now especially) within the precincts of a house or other building.', 'halaman', 'Can you please explain to me what the yard is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('young', 'B1', 'n.', 'Having lived for only a short time.', 'muda', 'She has a deep interest in learning more about the young and understanding its importance in our daily lives and how it affects us all in various ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('youth', 'B1', 'n.', 'The quality or state of being young.', 'masa muda / pemuda', 'Can you please explain to me what the youth is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('abandon', 'B2', 'v.', 'To give up or relinquish control of, to surrender or to give oneself over, or to yield to one''s emotions.', 'meninggalkan', 'The sailors had to abandon the sinking ship.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('absolute', 'B2', 'adj.', 'That which is independent of context-dependent interpretation, inviolate, fundamental.', 'mutlak', 'You have my absolute and complete trust and confidence in this matter without any doubt or hesitation.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('academic', 'B2', 'n.', '(usually capitalized) A follower of Plato, a Platonist.', 'akademis', 'She had a very successful academic career and graduated at the top of her class with high honors.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('acceptable', 'B2', 'adj.', 'Worthy, decent, sure of being accepted or received with at least moderate pleasure', 'dapat diterima', 'Your behavior at the meeting was not acceptable and you need to offer a sincere apology.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('accompany', 'B2', 'v.', 'To go with or attend as a companion or associate; to keep company with; to go along with.', 'menemani', 'She accompanied her friend to the hospital.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('account', 'B2', 'v.', 'A registry of pecuniary transactions; a written or printed statement of business dealings or debts and credits, and also of other things subjected to a reckoning or review.', 'mempertanggungjawabkan', 'Can you account for where you were last night?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('accurate', 'B2', 'adj.', 'Telling the truth or giving a true result; exact; not defective or faulty', 'akurat', 'The information in the report must be completely accurate and based on verified facts and reliable data sources.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('accuse', 'B2', 'v.', 'To find fault with, blame, censure', 'menuduh', 'He was accused of stealing money from the company.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('acknowledge', 'B2', 'v.', 'To admit the knowledge of; to recognize as a fact or truth; to declare one''s belief in', 'mengakui', 'She acknowledged her mistake and apologized.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('acquire', 'B2', 'v.', 'To get.', 'memperoleh', 'She acquired valuable skills from her previous job.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('actual', 'B2', 'adj.', 'Existing in fact; real; not imagined.', 'aktual / nyata', 'The view from the top of the mountain was absolutely actual beyond words or description.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('adapt', 'B2', 'v.', 'To make suitable; to make to correspond; to fit or suit', 'beradaptasi', 'It takes time to adapt to a new environment.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('additional', 'B2', 'adj.', 'Something added.', 'tambahan', 'We need to find a more additional approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('address', 'B2', 'v.', 'To prepare oneself.', 'alamat', 'What is your current email address so I can send you the important documents?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('administration', 'B2', 'n.', 'The act of administering; government of public affairs; the service rendered, or duties assumed, in conducting affairs; the conducting of any office or employment; direction.', 'administrasi', 'He wrote a comprehensive and detailed report about the administration for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('adopt', 'B2', 'v.', 'To take by choice into relationship (a child, heir, friend, citizen, etc.)', 'mengadopsi', 'They decided to adopt a child from an orphanage.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('advance', 'B2', 'n., v., adj.', 'A forward move; improvement or progression.', 'maju', 'Technology has advanced rapidly in the past decade.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('affair', 'B2', 'n.', '(often in the plural) Something which is done or is to be done; business of any kind, commercial, professional, or public.', 'urusan', 'The company is investigating the financial affair.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('afterwards', 'B2', 'adv.', '(temporal location) At a later or succeeding time.', 'kemudian / setelahnya', 'Everything happened afterwards as we had expected and planned.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('agency', 'B2', 'n.', 'The capacity, condition, or state of acting or of exerting power.', 'agensi / badan', 'The teacher gave a clear and thorough explanation about the agency to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('agenda', 'B2', 'n.', 'A temporally organized plan for matters to be attended to.', 'agenda', 'I found an insightful article about the agenda in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('aggressive', 'B2', 'adj.', 'Characterized by aggression; unjustly attacking; prone to behave in a way that involves attacking or arguing.', 'agresif', 'The results of the experiment were aggressive according to the researchers who conducted the study and analyzed the collected data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('aid', 'B2', 'n., v.', 'Help or support; assistance.', 'bantuan', 'The organization provides aid to disaster victims.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('aircraft', 'B2', 'n.', 'A vehicle capable of atmospheric flight due to interaction with the air, such as buoyancy or lift', 'pesawat terbang', 'He wrote a comprehensive and detailed report about the aircraft for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('alarm', 'B2', 'v.', 'To call to arms for defense', 'alarm', 'The fire alarm went off in the middle of the night.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('alter', 'B2', 'v.', 'To change the form or structure of.', 'mengubah', 'We need to alter our plans due to the weather.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('amount', 'B2', 'v.', 'The total quantity or sum of something.', 'berjumlah', 'She needs to amount before the deadline to avoid any penalties or problems.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('anger', 'B2', 'n.', 'A strong feeling of annoyance or hostility.', 'kemarahan', 'He needed to find a healthy way to deal with his anger and frustration instead of keeping it bottled up inside.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('angle', 'B2', 'n.', 'The space between two intersecting lines; a way of approaching something.', 'sudut', 'Can you please explain to me what the angle is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('anniversary', 'B2', 'n.', 'A day that is an exact number of years (to the day) since a given significant event occurred. Often preceded by an ordinal number indicating the number of years.', 'ulang tahun', 'They celebrated their tenth wedding anniversary.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('annual', 'B2', 'adj.', 'Happening once a year; yearly.', 'tahunan', 'The company holds an annual meeting for all employees.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('anxious', 'B2', 'adj.', 'Feeling worried or nervous.', 'cemas', 'She felt very anxious before her big job interview but she managed to stay calm.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('apparent', 'B2', 'adj.', 'Clearly visible; obvious; seeming real but not necessarily.', 'jelas', 'It was apparent that she was not telling the truth.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('apparently', 'B2', 'adv.', 'Plainly; clearly; manifestly; evidently.', 'rupanya', 'Apparently the meeting has been cancelled.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('appeal', 'B2', 'n., v.', 'An application for the removal of a cause or suit from an inferior to a superior judge or court for re-examination or review.', 'daya tarik / banding', 'The charity appeal raised thousands of dollars.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('approach', 'B2', 'n., v.', 'The act of drawing near; a coming or advancing near.', 'mendekati', 'We need to approach this problem carefully.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('appropriate', 'B2', 'adj.', 'Suitable or proper in the circumstances.', 'pantas', 'Please make sure to wear appropriate formal clothing to the important business meeting.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('approval', 'B2', 'n.', 'An expression granting permission; an indication of agreement with a proposal; an acknowledgement that a person, thing or event meets requirements.', 'persetujuan', 'He wrote a comprehensive and detailed report about the approval for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('approve', 'B2', 'v.', 'To sanction officially; to ratify; to confirm; to set as satisfactory.', 'menyetujui', 'The committee approved the budget proposal.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('arise', 'B2', 'v.', 'To come up from a lower to a higher position.', 'timbul', 'If any issues arise, please let me know immediately.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('armed', 'B2', 'adj.', 'To take by the arm; to take up in one''s arms.', 'bersenjata', 'We need to find a more armed approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('arms', 'B2', 'n.', 'The portion of the upper human appendage, from the shoulder to the wrist and sometimes including the hand.', 'lengan / senjata', 'She has a deep interest in learning more about the arms and understanding its importance in our daily lives and how it affects us all in various ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('artificial', 'B2', 'adj.', 'Made by human beings; not natural.', 'buatan', 'The flowers are artificial but they look very real.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('artistic', 'B2', 'adj.', 'Having or revealing creative skill.', 'artistik', 'We need to find a more artistic approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ashamed', 'B2', 'adj.', 'To feel shame; to be ashamed.', 'malu', 'She felt deeply ashamed of her rude behavior at the dinner party.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('aspect', 'B2', 'n.', 'Any specific feature, part, or element of something.', 'aspek', 'We need to consider every aspect of the problem.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('assess', 'B2', 'v.', 'To determine, estimate or judge the value of; to evaluate', 'menilai', 'The teacher will assess the students'' performance.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('assessment', 'B2', 'n.', 'The act of assessing or an amount (of tax, levy or duty etc) assessed.', 'penilaian', 'He wrote a comprehensive and detailed report about the assessment for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('associate', 'B2', 'v.', 'To join in or form a league, union, or association.', 'mengaitkan', 'I associate summer with beach holidays.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('associated', 'B2', 'adj.', 'Connected or linked with something.', 'terkait / berhubungan', 'The weather today is quite associated compared to yesterday when it was much nicer outside.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('association', 'B2', 'n.', 'The act of associating.', 'asosiasi / perkumpulan', 'They had a very productive and engaging discussion about the association during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('assume', 'B2', 'v.', 'To authenticate by means of belief; to surmise; to suppose to be true, especially without proof', 'berasumsi', 'I assume you have already read the email I sent.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('attempt', 'B2', 'n., v.', 'The action of trying at something.', 'mencoba', 'He made a brave attempt to climb the dangerous mountain.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('back', 'B2', 'v.', 'In the opposite direction from the front; toward the rear.', 'kembali', 'I will call you back later this evening after I get home from work and have dinner.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bacteria', 'B2', 'n.', 'A type, species, or strain of bacterium.', 'bakteri', 'The teacher gave a clear and thorough explanation about the bacteria to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bar', 'B2', 'v.', 'A solid, more or less rigid object of metal or wood with a uniform cross-section smaller than its length.', 'menghalangi', 'It is important to know when to bar and when to wait for the right moment.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('barrier', 'B2', 'n.', 'A structure that blocks movement; an obstacle.', 'hambatan', 'Language can be a barrier to communication.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('basically', 'B2', 'adv.', 'In a fundamental, essential or basic manner', 'pada dasarnya', 'Basically you just need to carefully follow the step by step instructions and you will be fine.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('battle', 'B2', 'v.', 'To join in battle', 'pertempuran', 'The battle lasted for three days and nights.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bear (deal with)', 'B2', 'v.', 'To endeavour to depress the price of, or prices in.', 'menanggung / menghadapi', 'They watched the instructor carefully bear (deal with) with great skill and precision.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('beat', 'B2', 'n.', 'A stroke; a blow.', 'mengalahkan', 'Our team managed to beat the defending champions.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('beg', 'B2', 'v.', 'To request the help of someone, often in the form of money.', 'memohon / mengemis', 'It is important to know when to beg and when to wait for the right moment.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('being', 'B2', 'n.', 'A living creature.', 'makhluk', 'They had a very productive and engaging discussion about the being during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bent', 'B2', 'adj.', 'To cause (something) to change its shape into a curve, by physical force, chemical action, or any other means.', 'bengkok / melengkung', 'He gave a remarkably bent performance on stage that impressed everyone in the audience.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bet', 'B2', 'v., n.', 'A wager, an agreement between two parties that a stake (usually money) will be paid by the loser to the winner (the winner being the one who correctly forecast the outcome of an event).', 'bertaruh / taruhan', 'She has been studying the bet for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('beyond', 'B2', 'prep., adv.', 'At or to the further side of; outside the limits of.', 'melampaui / di luar', 'The post office is beyond the bank and the supermarket building.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bill', 'B2', 'v.', 'To dig, chop, etc., with a bill.', 'tagihan', 'Excuse me waiter could you please bring me the bill when you get a chance? I am ready to pay now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bitter', 'B2', 'adj.', '(usually in the plural bitters) A liquid or powder, made from bitter herbs, used in mixed drinks or as a tonic.', 'pahit', 'The dark chocolate has a slightly bitter taste but it is still very enjoyable and delicious.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('blame', 'B2', 'v., n.', 'Censure.', 'menyalahkan', 'Don''t blame others for your own mistakes.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('blind', 'B2', 'adj.', 'Unable to see; lacking perception.', 'buta', 'We need to find a more blind approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bond', 'B2', 'n.', 'Evidence of a long-term debt, by which the bond issuer (the borrower) is obliged to pay interest when due, and repay the principal at maturity, as specified on the face of the bond certificate. The rights of the holder are specified in the bond indenture, which contains the legal terms and conditions under which the bond was issued. Bonds are available in two forms: registered bonds, and bearer bonds.', 'obligasi / ikatan', 'I found an insightful article about the bond in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('border', 'B2', 'v.', 'To put a border on something.', 'berbatasan', 'The company plans to border next month according to the business schedule.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('breast', 'B2', 'n.', 'Either of the two organs on the front of a female human''s chest, which contain the mammary glands; also the analogous organs in males.', 'dada / payudara', 'The concept of breast plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('brief', 'B2', 'adj.', 'Short in duration or length; concise.', 'singkat', 'The manager gave a brief presentation about the companys quarterly results and performance.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('broad', 'B2', 'adj.', 'Having great width; wide; general.', 'luas / lebar', 'The garden looks especially broad in the spring season when all the beautiful flowers are in full bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('broadcast', 'B2', 'v., n.', 'A transmission of a radio or television programme intended to be received by anyone with a receiver.', 'siaran', 'The news broadcast reported on the latest developments.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('budget', 'B2', 'n.', 'The amount of money or resources earmarked for a particular institution, activity or time-frame.', 'anggaran', 'The concept of budget plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bullet', 'B2', 'n.', 'A projectile, usually of metal, shot from a gun at high speed.', 'peluru', 'The teacher gave a clear and thorough explanation about the bullet to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bunch', 'B2', 'n.', 'A group of similar things, either growing together, or in a cluster or clump, usually fastened together.', 'sekumpulan / seikat', 'The bunch is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('burn', 'B2', 'n.', 'A physical injury caused by heat, cold, electricity, radiation or caustic chemicals.', 'membakar', 'Be careful not to burn yourself on the hot stove.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('bush', 'B2', 'n.', 'A woody plant distinguished from a tree by its multiple stems and lower height, being usually less than six metres tall; a horticultural rather than strictly botanical category.', 'semak', 'I read a very interesting article about the bush in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('but', 'B2', 'prep.', 'Used to introduce a phrase that contrasts with what was said previously.', 'tetapi', 'I really wanted to go to the party and have fun with my friends but unfortunately I was feeling far too exhausted and tired to go out.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cable', 'B2', 'n.', '(material) A long object used to make a physical connection.', 'kabel', 'I found an insightful article about the cable in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('calculate', 'B2', 'v.', 'To determine the value of something or the solution to something by a mathematical process.', 'menghitung', 'The company plans to calculate next month according to the business schedule.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cancel', 'B2', 'v.', 'To cross out something with lines etc.', 'membatalkan', 'She makes it a habit to cancel every single day without missing or failing.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cancer', 'B2', 'n.', 'A disease in which the cells of a tissue undergo uncontrolled (and often rapid) proliferation.', 'kanker', 'The concept of cancer plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('capable', 'B2', 'adj.', 'Able and efficient; having the ability needed for a specific task; having the disposition to do something; permitting or being susceptible to something.', 'mampu / cakap', 'The weather today is quite capable compared to yesterday when it was much nicer outside.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('capacity', 'B2', 'n.', 'The ability to hold, receive or absorb', 'kapasitas / kemampuan', 'They had a very productive and engaging discussion about the capacity during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('capture', 'B2', 'v., n.', 'An act of capturing; a seizing by force or stratagem.', 'menangkap / penangkapan', 'He wrote a comprehensive and detailed report about the capture for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cast', 'B2', 'n., v.', 'An act of throwing.', 'melempar / pemeran', 'He wrote a comprehensive and detailed report about the cast for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('catch', 'B2', 'n.', 'The act of seizing or capturing.', 'tangkapan', 'She has been studying the catch for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cell', 'B2', 'n.', 'A single-room dwelling for a hermit.', 'sel', 'The cell is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('chain', 'B2', 'v.', 'To fasten something with a chain.', 'merantai / mengikat', 'It is important to know when to chain and when to wait for the right moment.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('chair', 'B2', 'v.', 'To act as chairperson at', 'kursi', 'Please pull up a chair and come join our interesting conversation about the latest news.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('chairman', 'B2', 'n.', 'A person presiding over a meeting.', 'ketua', 'I read a very interesting article about the chairman in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('challenge', 'B2', 'v.', 'To invite', 'menantang', 'They watched the instructor carefully challenge with great skill and precision.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('characteristic', 'B2', 'n., adj.', 'A distinguishing feature of a person or thing.', 'karakteristik / ciri khas', 'They had a very productive and engaging discussion about the characteristic during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('chart', 'B2', 'v.', 'A graphical representation of data; a map or diagram.', 'grafik / bagan', 'The colorful chart clearly illustrates the impressive growth of the company over the past five successful years.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('chief', 'B2', 'adj., n.', 'Most important; main; having the highest rank.', 'kepala / utama', 'She has been studying the chief for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('circumstance', 'B2', 'n.', 'That which attends, or relates to, or in some way affects, a fact or event', 'keadaan / situasi', 'She has a deep interest in learning more about the circumstance and understanding its importance in our daily lives and how it affects us all in various ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cite', 'B2', 'v.', 'To quote; to repeat, as a passage from a book, or the words of another.', 'mengutip', 'She makes it a habit to cite every single day without missing or failing.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('citizen', 'B2', 'n.', 'A resident of a city or town, especially one with legally-recognized rights or duties.', 'warga negara', 'The citizen is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('civil', 'B2', 'adj.', 'Having to do with people and government office as opposed to the military or religion.', 'sipil', 'The garden looks especially civil in the spring season when all the beautiful flowers are in full bloom.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('classic', 'B2', 'adj., n.', 'Of the highest quality; typical; traditional.', 'klasik', 'He wrote a comprehensive and detailed report about the classic for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('close1', 'B2', 'n.', 'The act of shutting or the state of being shut.', 'penutupan', 'She has a deep interest in learning more about the close1 and understanding its importance in our daily lives and how it affects us all in various ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('closely', 'B2', 'adv.', 'In a close manner.', 'erat / dengan dekat', 'She completed the task closely and without making any mistakes at all.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('collapse', 'B2', 'v., n.', 'The act of collapsing.', 'runtuh / keruntuhan', 'The teacher gave a clear and thorough explanation about the collapse to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('combination', 'B2', 'n.', 'A joining or mixture of things.', 'kombinasi', 'They had a very productive and engaging discussion about the combination during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('comfort', 'B2', 'n., v.', 'Contentment, ease.', 'kenyamanan / menghibur', 'I found an insightful article about the comfort in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('command', 'B2', 'n., v.', 'An order to do something.', 'perintah / memerintah', 'I read a very interesting article about the command in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('commission', 'B2', 'n., v.', 'A sending or mission (to do or accomplish something).', 'komisi', 'She has a deep interest in learning more about the commission and understanding its importance in our daily lives and how it affects us all in various ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('commitment', 'B2', 'n.', 'The act or an instance of committing, putting in charge, keeping, or trust, especially:', 'komitmen', 'I read a very interesting article about the commitment in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('committee', 'B2', 'n.', 'A body of one or more persons convened for the accomplishment of some specific purpose, typically with formal protocols.', 'komite / panitia', 'The committee is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('commonly', 'B2', 'adv.', 'As a rule; frequently; usually', 'biasanya', 'English is very commonly used as a second language in many countries all around the world.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('complex', 'B2', 'n.', 'Made of many parts; complicated.', 'kompleks', 'She has been studying the complex for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('complicated', 'B2', 'adj.', 'Difficult or convoluted.', 'rumit / sulit', 'The view from the top of the mountain was absolutely complicated beyond words or description.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('component', 'B2', 'n.', 'One part of a larger system.', 'komponen', 'I read a very interesting article about the component in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('concentration', 'B2', 'n.', 'The act, process or ability of concentrating; the process of becoming concentrated, or the state of being concentrated.', 'konsentrasi', 'The concept of concentration plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('concept', 'B2', 'n.', 'An abstract idea or general notion.', 'konsep', 'Can you please explain to me what the concept is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('concern', 'B2', 'n., v.', 'Worry; a matter of interest.', 'kekhawatiran / perhatian', 'They had a very productive and engaging discussion about the concern during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('concerned', 'B2', 'adj.', 'Worried; involved in something.', 'khawatir / prihatin', 'We need to find a more concerned approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('conduct', 'B2', 'v., n.', 'The act or method of controlling or directing', 'melakukan / perilaku', 'The teacher gave a clear and thorough explanation about the conduct to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('confidence', 'B2', 'n.', 'Self-assurance.', 'kepercayaan diri', 'She spoke with great confidence and authority during her presentation to the board of directors.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('conflict', 'B2', 'n., v.', 'A disagreement; a fight.', 'konflik', 'The conflict is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('confusing', 'B2', 'adj.', 'Difficult to understand; unclear.', 'membingungkan', 'The view from the top of the mountain was absolutely confusing beyond words or description.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('conscious', 'B2', 'adj.', 'Aware of one''s surroundings; deliberate.', 'sadar', 'He was still conscious after the accident but he felt very dizzy and confused and disoriented.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('conservative', 'B2', 'adj., n.', 'Preferring traditional styles and values.', 'konservatif', 'The conservative is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('consideration', 'B2', 'n.', 'Careful thought; a factor taken into account.', 'pertimbangan', 'I read a very interesting article about the consideration in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('consistent', 'B2', 'adj.', 'Always acting in the same way; unchanging.', 'konsisten', 'The results of the experiment were consistent according to the researchers who conducted the study and analyzed the collected data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('constant', 'B2', 'adj.', 'Occurring continuously; never changing.', 'terus-menerus', 'The constant noise from the construction site next door has been very disturbing all week long.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('constantly', 'B2', 'adv.', 'Continuously; all the time.', 'terus-menerus', 'She answered the question constantly and with great confidence.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('construct', 'B2', 'v.', 'To build; to create.', 'membangun / menyusun', 'She makes it a habit to construct every single day without missing or failing.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('construction', 'B2', 'n.', 'The act of building.', 'konstruksi / pembangunan', 'She has been studying the construction for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('contemporary', 'B2', 'adj.', 'Someone or something living at the same time, or of roughly the same age as another.', 'kontemporer / masa kini', 'The weather today is quite contemporary compared to yesterday when it was much nicer outside.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('contest', 'B2', 'n., v.', 'Controversy', 'kontes / perlombaan', 'The contest is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('contract', 'B2', 'n., v.', 'An agreement between two or more parties, to perform a specific job or work order, often temporary or of fixed duration and usually governed by a written agreement.', 'kontrak', 'She recently signed a legally binding two year contract to work for the international company based in Singapore.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('contribute', 'B2', 'v.', 'To give something that is or becomes part of a larger whole.', 'berkontribusi', 'Everyone should contribute to protecting the environment.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('contribution', 'B2', 'n.', 'Something given or offered that adds to a larger whole.', 'kontribusi / sumbangan', 'I read a very interesting article about the contribution in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('convert', 'B2', 'v.', 'To transform or change', 'mengubah / mengonversi', 'She would like to learn how to convert correctly from an experienced teacher.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('convinced', 'B2', 'adj.', 'In a state of believing, especially from evidence but not necessarily.', 'yakin', 'We need to find a more convinced approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('core', 'B2', 'n., adj.', 'The central part of fruit, containing the kernels or seeds.', 'inti / bagian tengah', 'The teacher gave a clear and thorough explanation about the core to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('corporate', 'B2', 'adj.', 'A bond issued by a corporation.', 'perusahaan / korporat', 'We need to find a more corporate approach to solving this ongoing problem that we have been facing for such a long time now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('council', 'B2', 'n.', 'A committee that leads or governs (e.g. city council, student council).', 'dewan', 'He wrote a comprehensive and detailed report about the council for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('county', 'B2', 'n.', 'The land ruled by a count or a countess.', 'kabupaten', 'Can you please explain to me what the county is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('courage', 'B2', 'n.', 'The quality of being confident, not afraid or easily intimidated, but without being incautious or inconsiderate.', 'keberanian', 'It takes a tremendous amount of courage and inner strength to admit your mistakes and apologize sincerely for them.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('crash', 'B2', 'n., v.', 'A collision; to fall noisily.', 'menabrak', 'The car unfortunately lost control and crashed into a large tree on the side of the road but fortunately nobody was injured in the accident.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('creation', 'B2', 'n.', 'The act of bringing something into existence.', 'penciptaan', 'The concept of creation plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('creature', 'B2', 'n.', 'A living being; an animal or (sometimes derogatory) a human.', 'makhluk', 'She has a deep interest in learning more about the creature and understanding its importance in our daily lives and how it affects us all in various ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('credit', 'B2', 'v.', 'To believe', 'kredit', 'She decided to purchase the expensive laptop on credit and will be paying it off in convenient monthly installments over the course of the next year.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('crew', 'B2', 'n.', 'A group of people working on a ship, aircraft, or film.', 'awak / kru', 'I read a very interesting article about the crew in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('crisis', 'B2', 'n.', 'A crucial or decisive point or situation; a turning point.', 'krisis', 'The country unfortunately faced a severe and devastating economic crisis last year which affected millions of people across the entire nation.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('criterion', 'B2', 'n.', 'A standard by which something is judged.', 'kriteria', 'She has been studying the criterion for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('critic', 'B2', 'n.', 'A person who appraises the works of others.', 'kritikus', 'I found an insightful article about the critic in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('critical', 'B2', 'adj.', 'Expressing disapproval; very important; crucial.', 'kritis / penting', 'It is absolutely critical and vitally important that we finish and submit the final report on time before the strict deadline.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('criticism', 'B2', 'n.', 'The act of criticising; a critical judgment passed or expressed', 'kritik', 'The teacher gave a clear and thorough explanation about the criticism to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('criticize', 'B2', 'v.', 'To point out faults; to express disapproval.', 'mengkritik', 'She would like to learn how to criticize correctly from an experienced teacher.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('crop', 'B2', 'n.', 'A plant grown for food.', 'tanaman / hasil panen', 'The hardworking farmers successfully harvested all their crops just before the heavy rainy season arrived to prevent any damage or loss.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('crucial', 'B2', 'adj.', 'Essential or decisive for determining the outcome or future of something; extremely important.', 'sangat penting', 'It is absolutely crucial to carefully follow all the important safety instructions and guidelines when operating heavy machinery.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cry', 'B2', 'n.', 'A shedding of tears; the act of crying.', 'menangis', 'The baby started to cry because she was hungry and tired.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('cure', 'B2', 'v., n.', 'A method, device or medication that restores good health.', 'obat / penyembuhan', 'Medical scientists and researchers from all around the world are still actively working and searching for a complete and effective cure for various types of cancer.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('current', 'B2', 'n.', 'The generally unidirectional movement of a gas or fluid.', 'saat ini', 'What is the current local time in Tokyo Japan right now at this moment?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('curve', 'B2', 'n., v.', 'A gentle bend, such as in a road.', 'tikungan', 'The winding mountain road ahead has a very sharp and dangerous curve so please drive extremely slowly and carefully through this section.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('curved', 'B2', 'adj.', 'Having a shape that bends smoothly.', 'melengkung', 'The weather today is quite curved compared to yesterday when it was much nicer outside.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('date', 'B2', 'v.', 'The fruit of the date palm, Phoenix dactylifera, somewhat in the shape of an olive, containing a soft, sweet pulp and enclosing a hard kernel.', 'tanggal', 'What is todays date? I seem to have completely lost track of the days while being on vacation and relaxing.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('debate', 'B2', 'n., v.', 'An argument, or discussion, usually in an ordered or formal setting, often with more than two people, generally ending with a vote or other decision.', 'debat', 'There was a very heated and passionate debate among the members of parliament about the urgent issue of climate change and what steps should be taken to address it effectively.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('debt', 'B2', 'n.', 'An action, state of mind, or object one has an obligation to perform for another, adopt toward another, or give to another.', 'utang', 'She finally managed to pay off all her remaining student debt after diligently working and saving money for over ten long years.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('decent', 'B2', 'adj.', 'Appropriate; suitable for the circumstances.', 'layak', 'Every single person in our society deserves to have access to decent safe and affordable housing as a basic human right.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('declare', 'B2', 'v.', 'To make clear, explain, interpret.', 'menyatakan / mendeklarasikan', 'The president of the country officially declared a national holiday to celebrate and commemorate the historic occasion.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('decline', 'B2', 'v., n.', 'Downward movement, fall.', 'penurunan', 'The population of the small rural village has unfortunately been in steady decline over the past several decades as more and more young people have moved away to larger cities in search of better opportunities for work and education.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('decoration', 'B2', 'n.', 'The act of adorning, embellishing, or honoring; ornamentation.', 'dekorasi / hiasan', 'The entire room was beautifully and festively adorned with colorful and elaborate decorations for the exciting birthday celebration party.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('decrease', 'B2', 'v., n.', 'An amount by which a quantity is decreased.', 'penurunan / berkurang', 'The total number of students enrolled in the class this semester has unfortunately decreased significantly compared to last years enrollment numbers.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('deeply', 'B2', 'adv.', 'At depth, in a deep way.', 'sangat / secara mendalam', 'She was deeply moved and touched by the heartfelt speech that her best friend gave at the ceremony.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('defeat', 'B2', 'v., n.', 'To overcome in battle or contest.', 'kekalahan', 'The talented but unfortunate team suffered a very painful and heartbreaking defeat in the championship final match after giving their absolute best effort and playing with all their hearts.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('defence', 'B2', 'n.', 'The action of defending, of protecting from attack, danger or injury.', 'pertahanan', 'The ancient medieval stone castle was originally built with strong thick walls for defence against potential enemy attacks and invasions from outside forces.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('defend', 'B2', 'v.', 'To ward off attacks against; to fight to protect; to guard.', 'membela / mempertahankan', 'The brave soldier swore a solemn oath to defend his beloved country and protect its people with his own life if necessary without any hesitation.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('delay', 'B2', 'v., n.', 'A period of time before an event occurs; the act of delaying; procrastination; lingering inactivity.', 'penundaan / menunda', 'Our flight to Bali was unfortunately delayed by over three hours due to the severe and adverse weather conditions at the airport.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('deliberate', 'B2', 'adj.', 'Done consciously and intentionally.', 'sengaja / disengaja', 'Her careful and thoughtful choice of words during the speech was very deliberate and extremely precise in conveying exactly the message she intended to communicate to the audience.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('deliberately', 'B2', 'adv.', 'Intentionally, or after deliberation; not accidentally.', 'dengan sengaja', 'We need to act deliberately if we want to avoid any further delays.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('delight', 'B2', 'v., n.', 'Joy; pleasure.', 'kegembiraan', 'The young excited children all screamed and shouted with pure joy and delight when they saw the mountain of beautifully wrapped Christmas presents under the tree waiting for them on Christmas morning.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('delighted', 'B2', 'adj.', 'To give delight to; to affect with great pleasure; to please highly.', 'gembira / senang sekali', 'The movie we watched last night was surprisingly delighted and exceeded all of our expectations by a wide margin.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('delivery', 'B2', 'n.', 'The act of conveying something.', 'pengiriman', 'She has been studying the delivery for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('demand', 'B2', 'n., v.', 'The desire to purchase goods and services.', 'permintaan', 'There is currently an extremely high and growing demand for skilled and experienced software engineers in the competitive technology job market right now.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('demonstrate', 'B2', 'v.', 'To show how to use (something).', 'mendemonstrasikan', 'The experienced science teacher carefully demonstrated the correct and safe way to conduct the complex chemistry experiment to the students before allowing them to attempt it on their own.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('deny', 'B2', 'v.', 'To disallow or reject.', 'menyangkal', 'The accused man firmly and vehemently denied any involvement whatsoever in the robbery or any knowledge of the crime that had been committed.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('depressed', 'B2', 'adj.', 'To press down.', 'sedih / depresi', 'She felt extremely depressed and hopeless after unexpectedly losing her stable job that she had held for many years without any warning or prior notice.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('depressing', 'B2', 'adj.', 'To press down.', 'mengkhawatirkan', 'The bleak and pessimistic economic news and reports that have been coming out recently are very depressing and concerning to hear and read about for everyone who is affected.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('depth', 'B2', 'n.', 'The vertical distance below a surface; the degree to which something is deep', 'kedalaman', 'The maximum depth of the vast ocean in this particular area is over one thousand meters which is incredibly deep and mysterious.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('desert', 'B2', 'v.', '(usually in the plural) That which is deserved or merited; a just punishment or reward', 'gurun', 'The vast Sahara Desert is widely known and recognized as the largest hot desert in the entire world covering a massive area across the northern region of the African continent.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('deserve', 'B2', 'v.', 'To be entitled to, as a result of past actions; to be worthy to have.', 'pantas mendapat', 'You absolutely and truly deserve to take a well earned break and rest after all that incredibly hard work and dedicated effort you have put into completing this challenging project successfully on time.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('desire', 'B2', 'n., v.', 'Someone or something wished for.', 'keinginan / hasrat', 'Can you please explain to me what the desire is and why it is considered so important and significant in this particular context?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('desperate', 'B2', 'adj.', 'Feeling hopeless; extremely serious.', 'putus asa', 'After running for several miles under the scorching hot sun without any water to drink he was absolutely desperate and longing for a cold glass of refreshing water to quench his intense thirst.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('detail', 'B2', 'v.', 'Something small enough to escape casual notice.', 'detail / rincian', 'Could you please explain the proposed plan in greater detail with more specific information so that I can fully understand and grasp all the important aspects of it before we proceed?');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('detailed', 'B2', 'adj.', 'To explain in detail.', 'rinci / terperinci', 'The new policy has been detailed for the company and its employees according to the feedback that we have received so far from various stakeholders.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('detect', 'B2', 'v.', 'To discover or find by careful search, examination, or probing', 'mendeteksi', 'Specially trained dogs have the amazing ability to detect certain serious diseases in humans such as cancer simply by using their incredibly sensitive and powerful sense of smell.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dig', 'B2', 'v.', 'To break up or remove earth with a tool or hands.', 'menggali', 'The energetic and playful dog loves to dig large holes in the soft soil of the backyard garden whenever it gets the chance to go outside and explore the yard.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('disc', 'B2', 'n.', 'A flat circular object; a record or CD.', 'cakram / piringan', 'He wrote a comprehensive and detailed report about the disc for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('discipline', 'B2', 'n.', 'A controlled behaviour; self-control.', 'disiplin', 'Learning how to play a complex musical instrument at a high level of proficiency requires a tremendous amount of patience dedication and consistent self discipline in order to practice regularly and make steady progress over time.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('discount', 'B2', 'v.', 'A reduction in price.', 'memberi diskon', 'They watched the instructor carefully discount with great skill and precision.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dishonest', 'B2', 'adj.', 'Not truthful; deceptive.', 'tidak jujur', 'The food at the new restaurant tastes incredibly dishonest and we highly recommend it to everyone who visits the area.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dismiss', 'B2', 'v.', 'To send away; to reject.', 'membubarkan', 'The teacher decided to dismiss the class early that afternoon because it was the day before the long holiday weekend and everyone was already very excited and looking forward to the break.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('display', 'B2', 'v., n.', 'To show; a demonstration.', 'pameran', 'The local history museum has a fascinating and impressive display of ancient artifacts archaeological treasures and historical objects that were discovered and excavated from various sites in the region.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('distribute', 'B2', 'v.', 'To give out; to spread.', 'mendistribusikan / membagikan', 'They decided to distribute together as a team to achieve their shared common goal.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('distribution', 'B2', 'n.', 'An act of distributing or state of being distributed.', 'distribusi', 'I read a very interesting article about the distribution in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('district', 'B2', 'n.', 'An area of a city or region.', 'distrik / wilayah', 'The concept of district plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('divide', 'B2', 'n.', 'A thing that divides.', 'membagi', 'Please divide the pizza into eight equal slices.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('division', 'B2', 'n.', 'The act of dividing; a section.', 'pembagian / divisi', 'She has been studying the division for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('document', 'B2', 'v.', 'An original or official paper used as the basis, proof, or support of anything else, including any writing, book, or other instrument conveying information pertinent to such proof or support.', 'mendokumentasikan', 'He learned how to document properly from his experienced and patient mentor.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('domestic', 'B2', 'adj.', 'Relating to home or family; not foreign.', 'domestik / dalam negeri', 'The results of the experiment were domestic according to the researchers who conducted the study and analyzed the collected data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dominate', 'B2', 'v.', 'Ruling; governing; prevailing', 'mendominasi', 'They decided to dominate together as a team to achieve their shared common goal.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('downwards', 'B2', 'adv.', 'Towards a lower place; towards what is below.', 'ke bawah', 'She answered the question downwards and with great confidence.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dozen', 'B2', 'n., det.', 'A set of twelve.', 'lusin', 'They had a very productive and engaging discussion about the dozen during the team meeting yesterday afternoon that lasted for over an hour.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('draft', 'B2', 'n., v.', 'A current of air, usually coming into a room or vehicle.', 'konsep / rancangan', 'The concept of draft plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('drag', 'B2', 'v.', 'To pull something along with force.', 'menyeret / menarik', 'She would like to learn how to drag correctly from an experienced teacher.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('dramatic', 'B2', 'adj.', 'Of or relating to the drama.', 'dramatis', 'Her presentation about the topic was very dramatic and everyone in the audience found it engaging and informative.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('edit', 'B2', 'v.', 'A change to the text of a document.', 'menyunting / mengedit', 'The company plans to edit next month according to the business schedule.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('edition', 'B2', 'n.', 'A written work edited and published, as by a certain editor or in a certain manner.', 'edisi', 'He wrote a comprehensive and detailed report about the edition for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('efficient', 'B2', 'adj.', 'Achieving maximum productivity with minimum wasted effort.', 'efisien', 'He gave a remarkably efficient performance on stage that impressed everyone in the audience.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('elderly', 'B2', 'adj.', 'Old; past middle age.', 'lanjut usia', 'He gave a remarkably elderly performance on stage that impressed everyone in the audience.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('elect', 'B2', 'v.', 'One chosen or set apart.', 'memilih', 'The citizens will elect a new president next year.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('elsewhere', 'B2', 'adv.', 'In or to another place.', 'di tempat lain', 'She answered the question elsewhere and with great confidence.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('emerge', 'B2', 'v.', 'To come out from.', 'muncul', 'She would like to learn how to emerge correctly from an experienced teacher.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('emotional', 'B2', 'adj.', 'Relating to emotions; showing strong feelings.', 'emosional', 'The food at the new restaurant tastes incredibly emotional and we highly recommend it to everyone who visits the area.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('emphasis', 'B2', 'n.', 'Special importance given to something.', 'penekanan', 'The concept of emphasis plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('emphasize', 'B2', 'v.', 'To give special importance.', 'menekankan', 'Can you please emphasize this task for me? I would really appreciate your help.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('enable', 'B2', 'v.', 'To make possible.', 'memungkinkan', 'The scholarship enabled her to attend university.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('encounter', 'B2', 'v., n.', 'To meet unexpectedly.', 'menemui / bertemu', 'I read a very interesting article about the encounter in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('engage', 'B2', 'v.', 'To occupy; to participate.', 'melibatkan', 'The speaker engaged the audience with her interesting stories.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('enhance', 'B2', 'v.', 'To lift, raise up.', 'meningkatkan', 'Can you please enhance this task for me? I would really appreciate your help.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('enquiry', 'B2', 'n.', 'A question; an investigation.', 'pertanyaan / penyelidikan', 'She has been studying the enquiry for many years and has developed a deep understanding and appreciation of its various aspects and nuances.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('ensure', 'B2', 'v.', 'To make a pledge to (someone); to promise, guarantee (someone of something); to assure.', 'memastikan', 'Please ensure that all the windows are closed before you leave.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('enthusiasm', 'B2', 'n.', 'Possession by a god; divine inspiration or frenzy.', 'antusiasme / semangat', 'She has a deep interest in learning more about the enthusiasm and understanding its importance in our daily lives and how it affects us all in various ways.');
