INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('entire', 'B2', 'adj.', 'Whole; complete; including every part.', 'seluruh / utuh', 'Her presentation about the topic was very entire and everyone in the audience found it engaging and informative.');
