INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('equal', 'B2', 'n.', 'The same in quantity, size, degree, or value.', 'sebanding / setara', 'The equal is an important topic that is often discussed and debated by experts in the field and by people who are interested in learning more about it.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('establish', 'B2', 'v.', 'To make stable or firm; to confirm.', 'mendirikan', 'The company was established in 1998.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('estate', 'B2', 'n.', 'The collective property and liabilities of someone, especially a deceased person.', 'perkebunan / warisan', 'They had a very productive and engaging discussion about the estate during the team meeting yesterday afternoon that lasted for over an hour.');
