INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('evil', 'B2', 'adj., n.', 'Profoundly immoral and wicked.', 'jahat / kejahatan', 'I found an insightful article about the evil in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('examination', 'B2', 'n.', 'A formal test; a close inspection.', 'pemeriksaan / ujian', 'I read a very interesting article about the examination in the newspaper this morning and it was quite informative and thought provoking.');
