INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('existence', 'B2', 'n.', 'The state of being real.', 'keberadaan / eksistensi', 'The concept of existence plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('expectation', 'B2', 'n.', 'A belief about the future.', 'harapan', 'The concept of expectation plays an important role in our everyday lives and activities in ways that we may not even fully realize or appreciate.');
