INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('exploration', 'B2', 'n.', 'The process of exploring.', 'eksplorasi / penjelajahan', 'The teacher gave a clear and thorough explanation about the exploration to help the students understand the concept better and more deeply.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('expose', 'B2', 'v.', 'To reveal, uncover, make visible, bring to light, introduce to.', 'mengekspos / membuka', 'They watched the instructor carefully expose with great skill and precision.');
