INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('extent', 'B2', 'n.', 'The size or scope of something.', 'tingkat / luas', 'I found an insightful article about the extent in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('external', 'B2', 'adj.', 'Relating to the outside.', 'eksternal / luar', 'The garden looks especially external in the spring season when all the beautiful flowers are in full bloom.');
