INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('failure', 'B2', 'n.', 'State or condition of not meeting a desirable or intended objective, opposite of success.', 'kegagalan', 'I read a very interesting article about the failure in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('faith', 'B2', 'n.', 'A trust or confidence in the intentions or abilities of a person, object, or ideal from prior empirical evidence.', 'iman / keyakinan', 'They had a very productive and engaging discussion about the faith during the team meeting yesterday afternoon that lasted for over an hour.');
