INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('feel', 'B2', 'n.', 'A quality of an object experienced by touch.', 'perasaan / rabaan', 'I read a very interesting article about the feel in the newspaper this morning and it was quite informative and thought provoking.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('fellow', 'B2', 'adj.', 'A colleague or partner.', 'sesama / rekan', 'Her presentation about the topic was very fellow and everyone in the audience found it engaging and informative.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('figure', 'B2', 'v.', 'A drawing or diagram conveying information.', 'memperhitungkan / membayangkan', 'The team will figure after they finish reviewing all the available data.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('file', 'B2', 'v.', 'A collection of papers collated and archived together.', 'mengarsipkan / memfiling', 'He learned how to file properly from his experienced and patient mentor.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('finance', 'B2', 'n., v.', 'The management of money and other assets.', 'keuangan / membiayai', 'I read a very interesting article about the finance in the newspaper this morning and it was quite informative and thought provoking.');
