INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('firm', 'B2', 'n.', 'Not yielding to pressure; solid; stable.', 'perusahaan / teguh', 'I found an insightful article about the firm in a magazine that I was reading last night before I went to sleep.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('fix', 'B2', 'n.', 'A repair or corrective action.', 'memperbaiki', 'Can you fix the leaky faucet in the bathroom?');
