INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('folding', 'B2', 'adj.', 'Designed to fold', 'lipat', 'The movie we watched last night was surprisingly folding and exceeded all of our expectations by a wide margin.');
