INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('fuel', 'B2', 'v.', 'To provide with fuel.', 'mengisi bahan bakar', 'They decided to fuel together as a team to achieve their shared common goal.');
