INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('fundamental', 'B2', 'adj.', 'Forming a necessary base; primary; essential.', 'fundamental / mendasar', 'Her presentation about the topic was very fundamental and everyone in the audience found it engaging and informative.');
