INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wound', 'B2', 'n., v.', 'An injury, such as a cut, stab, or tear, to a (usually external) part of the body.', 'luka', 'She has a deep interest in learning more about the wound and understanding its importance in our daily lives and how it affects us all in various ways.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wrap', 'B2', 'v.', 'To enclose (an object) completely in any flexible, thin material such as fabric or paper.', 'membungkus', 'Please wrap the gift in beautiful paper.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('wrong', 'B2', 'n.', 'Not correct or true; mistaken.', 'salah', 'He wrote a comprehensive and detailed report about the wrong for his final project submission and presentation to the class.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('yet', 'B2', 'conj.', '(usually with negative) Thus far; up to the present; up to some specified time; still', 'namun / tetapi', 'He is not only intelligent yet also very kind and generous.');
INSERT INTO words (word, level, kind, definition, indonesia, sentence_example) VALUES ('zone', 'B2', 'n.', 'Each of the five regions of the earth''s surface into which it was divided by climatic differences, namely the torrid zone (between the tropics), two temperate zones (between the tropics and the polar circles), and two frigid zones (within the polar circles).', 'zona', 'Can you please explain to me what the zone is and why it is considered so important and significant in this particular context?');
